 1→import { Command, Flags } from '@oclif/core';
 2→import { getClient } from '../../lib/api-client.js';
 3→import { createOutput } from '../../lib/output.js';
 4→
 5→export default class CollectionCreate extends Command {
 6→  static description = 'Create a new collection';
 7→
 8→  static examples = [
 9→    '<%= config.bin %> <%= command.id %> --name "My Tools"',
10→    '<%= config.bin %> <%= command.id %> --name "Web Scrapers" --description "Tools for web scraping" --public',
11→  ];
12→
13→  static flags = {
14→    name: Flags.string({
15→      char: 'n',
16→      description: 'Collection name',
17→      required: true,
18→    }),
19→    description: Flags.string({
20→      char: 'd',
21→      description: 'Collection description',
22→    }),
23→    public: Flags.boolean({
24→      description: 'Make collection public',
25→      default: false,
26→    }),
27→    json: Flags.boolean({
28→      description: 'Output in JSON format',
29→      default: false,
30→    }),
31→    verbose: Flags.boolean({
32→      char: 'v',
33→      description: 'Show verbose output',
34→      default: false,
35→    }),
36→  };
37→
38→  async run(): Promise<void> {
39→    const { flags } = await this.parse(CollectionCreate);
40→    const output = createOutput(flags);
41→    const client = getClient();
42→
43→    if (!client.isAuthenticated()) {
44→      output.error('Not authenticated. Run `tpm auth login` first.');
45→      return;
46→    }
47→
48→    const spinner = output.spinner('Creating collection...');
49→
50→    try {
51→      const response = await client.createCollection({
52→        name: flags.name,
53→        description: flags.description,
54→        isPublic: flags.public,
55→      });
56→
57→      spinner.stop();
58→
59→      if (!response.success || !response.data) {
60→        output.error(response.message || 'Failed to create collection');
61→        return;
62→      }
63→
64→      if (flags.json) {
65→        output.json(response.data);
66→        return;
67→      }
68→
69→      output.success(`Collection "${response.data.name}" created successfully`);
70→      output.newLine();
71→      output.keyValue('ID', response.data.id);
72→      if (response.data.slug) {
73→        output.keyValue('Slug', response.data.slug);
74→      }
75→      output.keyValue('Public', response.data.isPublic ? 'Yes' : 'No');
76→      output.newLine();
77→      output.text(`Add tools: tpm collection add ${response.data.id} <tool-id>`);
78→    } catch (error) {
79→      spinner.fail('Failed to create collection');
80→      output.error(
81→        error instanceof Error ? error.message : 'Unknown error',
82→        flags.verbose ? String(error) : undefined
83→      );
84→    }
85→  }
86→}
