  1→import * as http from 'node:http';
  2→import * as readline from 'node:readline';
  3→import { Command, Flags } from '@oclif/core';
  4→import { getClient } from '../../lib/api-client.js';
  5→import { createOutput } from '../../lib/output.js';
  6→
  7→interface MCPRequest {
  8→  jsonrpc: '2.0';
  9→  id: string | number;
 10→  method: string;
 11→  params?: Record<string, unknown>;
 12→}
