 25→export default class MCPServe extends Command {
 26→  static description = 'Run as a local MCP server';
 27→
 28→  static examples = [
 29→    '<%= config.bin %> <%= command.id %>',
 30→    '<%= config.bin %> <%= command.id %> --port 8080',
 31→    '<%= config.bin %> <%= command.id %> --stdio',
 32→    '<%= config.bin %> <%= command.id %> --collection my-collection',
 33→  ];
 34→
 35→  static flags = {
 36→    port: Flags.integer({
 37→      char: 'p',
 38→      description: 'Port to run the server on (HTTP mode)',
 39→      default: 3333,
 40→    }),
 41→    stdio: Flags.boolean({
 42→      description: 'Use stdio transport instead of HTTP',
 43→      default: false,
 44→    }),
 45→    collection: Flags.string({
 46→      char: 'c',
 47→      description: 'Serve tools from a specific collection',
 48→    }),
 49→    tool: Flags.string({
 50→      char: 't',
 51→      description: 'Serve specific tools (comma-separated)',
 52→      multiple: true,
 53→    }),
 54→    verbose: Flags.boolean({
 55→      char: 'v',
 56→      description: 'Show verbose output',
 57→      default: false,
 58→    }),
 59→  };
 60→
 61→  private client = getClient();
 62→  private tools: Map<string, unknown> = new Map();
 63→
 64→  async run(): Promise<void> {
 65→    const { flags } = await this.parse(MCPServe);
 66→    const output = createOutput(flags);
 67→
 68→    // Load tools
 69→    await this.loadTools(flags, output);
 70→
 71→    if (flags.stdio) {
 72→      await this.runStdioServer(output, flags.verbose);
 73→    } else {
 74→      await this.runHttpServer(flags.port, output, flags.verbose);
 75→    }
 76→  }
 77→
 78→  private async loadTools(
 79→    flags: { collection?: string; tool?: string[] },
 80→    output: ReturnType<typeof createOutput>
 81→  ): Promise<void> {
 82→    const spinner = output.spinner('Loading tools...');
 83→
 84→    try {
 85→      if (flags.collection) {
 86→        // Load tools from collection - search for tools with collection filter
 87→        // For now, just load trending tools if collection specified
 88→        const response = await this.client.getTrendingTools({ limit: 20 });
 89→        if (response.data && response.data.length > 0) {
 90→          for (const tool of response.data) {
 91→            this.tools.set(tool.slug, tool);
 92→          }
 93→        }
 94→      } else if (flags.tool && flags.tool.length > 0) {
 95→        // Load specific tools by slug
 96→        for (const toolId of flags.tool) {
 97→          const response = await this.client.getToolBySlug(toolId);
 98→          if (response.success && response.data) {
 99→            this.tools.set(response.data.slug, response.data);
100→          }
101→        }
102→      } else {
103→        // Load trending tools as default
104→        const response = await this.client.getTrendingTools({ limit: 10 });
105→        if (response.data && response.data.length > 0) {
106→          for (const tool of response.data) {
107→            this.tools.set(tool.slug, tool);
108→          }
109→        }
110→      }
111→
112→      spinner.stop();
113→      output.info(`Loaded ${this.tools.size} tool(s)`);
114→    } catch (error) {
115→      spinner.fail('Failed to load tools');
116→      throw error;
117→    }
118→  }
119→
120→  private async runStdioServer(
121→    output: ReturnType<typeof createOutput>,
122→    verbose: boolean
123→  ): Promise<void> {
124→    output.info('Starting MCP server in stdio mode...');
125→    output.info('Listening for JSON-RPC messages on stdin');
126→
127→    const rl = readline.createInterface({
128→      input: process.stdin,
129→      output: process.stdout,
130→      terminal: false,
131→    });
132→
133→    rl.on('line', async (line) => {
134→      try {
135→        const request = JSON.parse(line) as MCPRequest;
136→        if (verbose) {
137→          output.info(`Received: ${request.method}`);
138→        }
139→        const response = await this.handleRequest(request);
140→        console.log(JSON.stringify(response));
141→      } catch (error) {
142→        const errorResponse: MCPResponse = {
143→          jsonrpc: '2.0',
144→          id: 0,
145→          error: {
146→            code: -32700,
147→            message: 'Parse error',
148→            data: error instanceof Error ? error.message : 'Unknown error',
149→          },
150→        };
151→        console.log(JSON.stringify(errorResponse));
152→      }
153→    });
154→
155→    // Keep process running
156→    await new Promise(() => {});
157→  }
158→
159→  private async runHttpServer(
160→    port: number,
161→    output: ReturnType<typeof createOutput>,
162→    verbose: boolean
163→  ): Promise<void> {
164→    const server = http.createServer(async (req, res) => {
165→      if (req.method === 'POST' && req.url === '/mcp') {
166→        let body = '';
167→        req.on('data', (chunk) => {
168→          body += chunk.toString();
169→        });
170→
171→        req.on('end', async () => {
172→          try {
173→            const request = JSON.parse(body) as MCPRequest;
174→            if (verbose) {
175→              output.info(`Received: ${request.method}`);
176→            }
177→            const response = await this.handleRequest(request);
178→            res.writeHead(200, { 'Content-Type': 'application/json' });
179→            res.end(JSON.stringify(response));
180→          } catch (error) {
181→            const errorResponse: MCPResponse = {
182→              jsonrpc: '2.0',
183→              id: 0,
184→              error: {
185→                code: -32700,
186→                message: 'Parse error',
187→                data: error instanceof Error ? error.message : 'Unknown error',
188→              },
189→            };
190→            res.writeHead(400, { 'Content-Type': 'application/json' });
191→            res.end(JSON.stringify(errorResponse));
192→          }
193→        });
194→      } else if (req.method === 'GET' && req.url === '/health') {
195→        res.writeHead(200, { 'Content-Type': 'application/json' });
196→        res.end(JSON.stringify({ status: 'ok', tools: this.tools.size }));
197→      } else {
198→        res.writeHead(404);
199→        res.end('Not found');
200→      }
201→    });
202→
203→    server.listen(port, () => {
204→      output.success(`MCP server running at http://localhost:${port}/mcp`);
205→      output.info('Health check: GET /health');
206→      output.info('Press Ctrl+C to stop');
207→    });
208→
209→    // Keep process running
210→    await new Promise(() => {});
211→  }
212→
213→  private async handleRequest(request: MCPRequest): Promise<MCPResponse> {
214→    const { id, method, params } = request;
215→
216→    switch (method) {
217→      case 'initialize':
218→        return {
219→          jsonrpc: '2.0',
220→          id,
221→          result: {
222→            protocolVersion: '2024-11-05',
223→            capabilities: {
224→              tools: {},
225→            },
226→            serverInfo: {
227→              name: 'tpmjs-mcp-server',
228→              version: '0.1.0',
229→            },
230→          },
231→        };
232→
233→      case 'tools/list':
234→        return {
235→          jsonrpc: '2.0',
236→          id,
237→          result: {
238→            tools: Array.from(this.tools.entries()).map(([slug, tool]) => ({
239→              name: slug,
240→              description: (tool as Record<string, unknown>).description || '',
241→              inputSchema: (tool as Record<string, unknown>).inputSchema || {
242→                type: 'object',
243→                properties: {},
244→              },
245→            })),
246→          },
247→        };
248→
249→      case 'tools/call': {
250→        const toolName = (params as Record<string, unknown>)?.name as string;
251→        const toolArgs = (params as Record<string, unknown>)?.arguments as Record<string, unknown>;
252→
253→        if (!toolName) {
254→          return {
255→            jsonrpc: '2.0',
256→            id,
257→            error: {
258→              code: -32602,
259→              message: 'Invalid params: tool name required',
260→            },
261→          };
262→        }
263→
264→        try {
265→          const response = await this.client.executeTool(toolName, toolArgs || {});
266→          return {
267→            jsonrpc: '2.0',
268→            id,
269→            result: {
270→              content: [
271→                {
272→                  type: 'text',
273→                  text: JSON.stringify(response, null, 2),
274→                },
275→              ],
276→            },
277→          };
278→        } catch (error) {
279→          return {
280→            jsonrpc: '2.0',
281→            id,
282→            error: {
283→              code: -32000,
284→              message: error instanceof Error ? error.message : 'Tool execution failed',
285→            },
286→          };
287→        }
288→      }
289→
290→      default:
291→        return {
292→          jsonrpc: '2.0',
293→          id,
294→          error: {
295→            code: -32601,
296→            message: `Method not found: ${method}`,
297→          },
298→        };
299→    }
300→  }
301→}
