  1→import * as fs from 'node:fs';
  2→import { Args, Command, Flags } from '@oclif/core';
  3→import { createOutput } from '../../lib/output.js';
  4→
  5→type ClientType = 'claude' | 'cursor' | 'windsurf' | 'generic';
  6→
  7→export default class McpConfig extends Command {
  8→  static description = 'Generate MCP configuration for AI clients';
  9→
 10→  static examples = [
 11→    '<%= config.bin %> <%= command.id %> ajax/ajax-collection',
 12→    '<%= config.bin %> <%= command.id %> ajax/ajax-collection --client cursor',
 13→    '<%= config.bin %> <%= command.id %> ajax/ajax-collection --output ~/Library/Application\\ Support/Claude/claude_desktop_config.json',
 14→  ];
 15→
 16→  static flags = {
 17→    client: Flags.string({
 18→      char: 'c',
 19→      description: 'Target client (claude, cursor, windsurf, generic)',
 20→      default: 'claude',
 21→      options: ['claude', 'cursor', 'windsurf', 'generic'],
 22→    }),
 23→    output: Flags.string({
 24→      char: 'o',
 25→      description: 'Output file path (will merge with existing config)',
 26→    }),
 27→    json: Flags.boolean({
 28→      description: 'Output in JSON format',
 29→      default: false,
 30→    }),
 31→    'api-key': Flags.string({
 32→      char: 'k',
 33→      description: 'API key to include in config (optional)',
 34→    }),
 35→  };
 36→
 37→  static args = {
 38→    collection: Args.string({
 39→      description: 'Collection path (username/slug)',
 40→      required: true,
 41→    }),
 42→  };
 43→
 44→  async run(): Promise<void> {
 45→    const { args, flags } = await this.parse(McpConfig);
 46→    const output = createOutput(flags);
 47→
 48→    const [username, slug] = args.collection.split('/');
 49→    if (!username || !slug) {
 50→      output.error('Invalid collection path. Use format: username/collection-slug');
 51→      return;
 52→    }
 53→
 54→    const mcpUrl = `https://tpmjs.com/api/mcp/${username}/${slug}/sse`;
 55→    const clientType = flags.client as ClientType;
 56→
 57→    // Generate config based on client type
 58→    const config = generateConfig(clientType, mcpUrl, slug, flags['api-key']);
 59→
 60→    if (flags.json) {
 61→      output.json(config);
 62→      return;
 63→    }
 64→
 65→    if (flags.output) {
 66→      // Merge with existing config if file exists
 67→      let existingConfig: Record<string, unknown> = {};
 68→      if (fs.existsSync(flags.output)) {
 69→        try {
 70→          const content = fs.readFileSync(flags.output, 'utf-8');
 71→          existingConfig = JSON.parse(content);
 72→        } catch {
 73→          output.warning(`Could not parse existing config at ${flags.output}, creating new file`);
 74→        }
 75→      }
 76→
 77→      // Merge mcpServers
 78→      const existingServers =
 79→        typeof existingConfig.mcpServers === 'object' && existingConfig.mcpServers !== null
 80→          ? (existingConfig.mcpServers as Record<string, unknown>)
 81→          : {};
 82→      const mergedConfig = {
 83→        ...existingConfig,
 84→        mcpServers: {
 85→          ...existingServers,
 86→          ...(config.mcpServers as Record<string, unknown>),
 87→        },
 88→      };
 89→
 90→      fs.writeFileSync(flags.output, JSON.stringify(mergedConfig, null, 2));
 91→      output.success(`Config written to ${flags.output}`);
 92→      return;
 93→    }
 94→
 95→    // Output config to console
 96→    output.heading(`MCP Config for ${clientType}`);
 97→    output.text(output.dim(`Collection: ${args.collection}`));
 98→    output.text(output.dim(`URL: ${mcpUrl}`));
 99→    output.newLine();
100→
101→    output.subheading('Add to your config file:');
102→    output.code(JSON.stringify(config, null, 2), 'json');
103→
104→    output.newLine();
105→    output.text(output.dim(getConfigPath(clientType)));
106→  }
107→}
108→
109→function generateConfig(
110→  _client: ClientType,
111→  mcpUrl: string,
112→  name: string,
113→  apiKey?: string
114→): Record<string, unknown> {
115→  const serverName = `tpmjs-${name}`;
116→
117→  const baseConfig = {
118→    mcpServers: {
119→      [serverName]: {
120→        command: 'npx',
121→        args: ['-y', '@anthropic/mcp-remote', mcpUrl],
122→        ...(apiKey && {
123→          env: {
124→            TPMJS_API_KEY: apiKey,
125→          },
126→        }),
127→      },
128→    },
129→  };
130→
131→  return baseConfig;
132→}
133→
134→function getConfigPath(client: ClientType): string {
135→  switch (client) {
136→    case 'claude':
137→      return 'Config location: ~/Library/Application Support/Claude/claude_desktop_config.json (macOS)';
138→    case 'cursor':
139→      return 'Config location: ~/.cursor/mcp.json';
140→    case 'windsurf':
141→      return 'Config location: ~/.windsurf/mcp.json';
142→    default:
143→      return 'Consult your MCP client documentation for config location';
144→  }
145→}
