 82→interface JsonRpcResponse {
 83→  jsonrpc: '2.0';
 84→  id: string | number | null;
 85→  result?: unknown;
 86→  error?: { code: number; message: string };
 87→}
 88→
 89→/**
 90→ * Process a JSON-RPC request and return the response
 91→ */
 92→async function processJsonRpcRequest(
 93→  collectionId: string,
 94→  collectionName: string,
 95→  body: JsonRpcRequest,
 96→  isOwner: boolean,
 97→  trackingCtx?: TrackingContext,
 98→  headerEnvVars?: Record<string, string>
 99→): Promise<JsonRpcResponse> {
100→  const requestId = body.id ?? null;
101→
102→  switch (body.method) {
103→    case 'initialize':
104→      return handleInitialize(collectionName, requestId);
105→
106→    case 'tools/list':
107→      return await handleToolsList(collectionId, requestId);
108→
109→    case 'tools/call': {
110→      const params = body.params as {
111→        name: string;
112→        arguments?: Record<string, unknown>;
113→        env?: Record<string, string>;
114→      };
115→
116→      // For non-owners, use caller-provided env vars (or empty if not provided)
117→      // For owners, callerEnvVars is undefined so handleToolsCall uses stored env vars
118→      const callerEnvVars = isOwner ? undefined : params.env || {};
119→
120→      return await handleToolsCall(
121→        collectionId,
122→        params,
123→        requestId,
124→        callerEnvVars,
125→        trackingCtx,
126→        headerEnvVars
127→      );
128→    }
129→
130→    case 'notifications/initialized':
131→    case 'ping':
132→      return { jsonrpc: '2.0', id: requestId, result: {} };
133→
134→    default:
135→      return {
136→        jsonrpc: '2.0',
137→        id: requestId,
138→        error: { code: -32601, message: `Method not found: ${body.method}` },
139→      };
140→  }
141→}
