493→/**
494→ * GET /api/mcp/[username]/[slug]/[transport]
495→ * Returns server info (for http) or establishes SSE connection (for sse)
496→ * Allows owners to access their private collections when authenticated
497→ */
498→export async function GET(_request: NextRequest, context: RouteContext): Promise<Response> {
499→  try {
500→    const { username, slug, transport } = await context.params;
501→
502→    if (transport !== 'http' && transport !== 'sse') {
503→      return NextResponse.json({ error: `Invalid transport: ${transport}` }, { status: 400 });
504→    }
505→
506→    // First, find the user by username
507→    const user = await getUserByUsername(username);
508→
509→    if (!user) {
510→      return NextResponse.json(
511→        { error: `User '${username}' not found. Check the username in your MCP endpoint URL.` },
512→        { status: 404 }
513→      );
514→    }
515→
516→    // Then find the collection
517→    const collection = await getCollectionByUserIdAndSlugOrId(user.id, slug);
518→
519→    if (!collection) {
520→      return NextResponse.json(
521→        { error: `Collection '${slug}' not found for user '${username}'.` },
522→        { status: 404 }
523→      );
524→    }
525→
526→    // For GET requests, check if user can access this collection:
527→    // - Public collections are accessible to anyone
528→    // - Private collections are only accessible to the owner (when authenticated)
529→    if (!collection.isPublic) {
530→      const authResult = await authenticateRequest();
531→      if (!authResult.authenticated || authResult.userId !== collection.userId) {
532→        // Don't reveal existence of private collections
533→        return NextResponse.json({ error: 'Collection not found' }, { status: 404 });
534→      }
535→    }
536→
537→    if (transport === 'sse') {
538→      return handleSseGet(username, slug, collection.name, collection.description);
539→    }
540→
541→    // HTTP transport - return server info
542→    return NextResponse.json({
543→      name: `TPMJS: ${collection.name}`,
544→      description: collection.description,
545→      protocol: 'mcp',
546→      transport: 'http',
547→      endpoint: `/api/mcp/${username}/${slug}/http`,
548→    });
549→  } catch (error) {
550→    console.error('[MCP GET] Error:', error);
551→    const message = error instanceof Error ? error.message : 'Internal server error';
552→    return NextResponse.json({ error: message }, { status: 500 });
553→  }
554→}
