 28→/**
 29→ * Wrap a promise with a timeout
 30→ */
 31→function withTimeout<T>(promise: Promise<T>, ms: number, errorMessage: string): Promise<T> {
 32→  return Promise.race([
 33→    promise,
 34→    new Promise<T>((_, reject) => setTimeout(() => reject(new Error(errorMessage)), ms)),
 35→  ]);
 36→}
