 15→  apiKey?: string;
 16→  refreshToken?: string;
 17→  expiresAt?: string;
 18→}
 19→
 20→const CONFIG_DIR = path.join(os.homedir(), '.tpmjs');
 21→const CREDENTIALS_FILE = path.join(CONFIG_DIR, 'credentials.json');
 22→const HISTORY_DIR = path.join(CONFIG_DIR, 'history');
 23→
 24→// Ensure config directory exists
 25→function ensureConfigDir(): void {
 26→  if (!fs.existsSync(CONFIG_DIR)) {
 27→    fs.mkdirSync(CONFIG_DIR, { recursive: true, mode: 0o700 });
 28→  }
 29→}
 30→
 31→// Config store using Conf
 32→const configStore = new Conf<TpmConfig>({
 33→  projectName: 'tpmjs',
 34→  cwd: CONFIG_DIR,
 35→  configName: 'config',
 36→  defaults: {
 37→    apiUrl: 'https://tpmjs.com/api',
 38→    defaultOutput: 'human',
 39→    verbose: false,
 40→    analytics: false,
 41→  },
 42→});
 43→
 44→export function getConfig(): TpmConfig {
 45→  return configStore.store;
 46→}
 47→
 48→export function setConfig(config: Partial<TpmConfig>): void {
 49→  for (const [key, value] of Object.entries(config)) {
 50→    if (value !== undefined) {
 51→      configStore.set(key, value);
 52→    }
 53→  }
 54→}
 55→
 56→export function getConfigValue<K extends keyof TpmConfig>(key: K): TpmConfig[K] {
 57→  return configStore.get(key);
 58→}
 59→
 60→export function setConfigValue<K extends keyof TpmConfig>(key: K, value: TpmConfig[K]): void {
 61→  configStore.set(key, value);
 62→}
 63→
 64→export function resetConfig(): void {
 65→  configStore.clear();
 66→}
 67→
 68→// Credentials management with secure file permissions
 69→export function loadCredentials(): TpmCredentials | null {
 70→  ensureConfigDir();
 71→
 72→  if (!fs.existsSync(CREDENTIALS_FILE)) {
 73→    return null;
 74→  }
 75→
 76→  try {
 77→    const content = fs.readFileSync(CREDENTIALS_FILE, 'utf-8');
 78→    return JSON.parse(content) as TpmCredentials;
 79→  } catch {
 80→    return null;
 81→  }
 82→}
 83→
 84→export function saveCredentials(credentials: TpmCredentials): void {
 85→  ensureConfigDir();
 86→
 87→  const content = JSON.stringify(credentials, null, 2);
 88→  fs.writeFileSync(CREDENTIALS_FILE, content, { mode: 0o600 });
 89→}
 90→
 91→export function deleteCredentials(): void {
 92→  if (fs.existsSync(CREDENTIALS_FILE)) {
 93→    fs.unlinkSync(CREDENTIALS_FILE);
 94→  }
 95→}
 96→
 97→export function hasCredentials(): boolean {
 98→  const creds = loadCredentials();
 99→  return creds !== null && !!creds.apiKey;
100→}
101→
102→// Get API key from multiple sources (priority order)
103→export function getApiKey(): string | undefined {
104→  // 1. Environment variable
105→  if (process.env.TPMJS_API_KEY) {
106→    return process.env.TPMJS_API_KEY;
107→  }
108→
109→  // 2. Credentials file
110→  const creds = loadCredentials();
111→  if (creds?.apiKey) {
112→    return creds.apiKey;
113→  }
114→
115→  return undefined;
116→}
117→
118→// Get API URL
119→export function getApiUrl(): string {
120→  return process.env.TPMJS_API_URL ?? getConfigValue('apiUrl') ?? 'https://tpmjs.com/api';
121→}
122→
123→// History directory for conversation caching
124→export function getHistoryDir(): string {
125→  if (!fs.existsSync(HISTORY_DIR)) {
126→    fs.mkdirSync(HISTORY_DIR, { recursive: true, mode: 0o700 });
127→  }
128→  return HISTORY_DIR;
129→}
130→
131→// Config directory path
132→export function getConfigDir(): string {
133→  ensureConfigDir();
134→  return CONFIG_DIR;
135→}
