  6→
  7→interface MCPRequest {
  8→  jsonrpc: '2.0';
  9→  id: string | number;
 10→  method: string;
 11→  params?: Record<string, unknown>;
 12→}
 13→
 14→interface MCPResponse {
 15→  jsonrpc: '2.0';
 16→  id: string | number;
