  2→import { type NextRequest, NextResponse } from 'next/server';
  3→
  4→import { API_KEY_SCOPES } from '~/lib/api-keys';
  5→import { authenticateRequest, getClientMetadata, hasScope } from '~/lib/api-keys/middleware';
  6→import {
  7→  checkApiKeyRateLimit,
  8→  createRateLimitResponse,
  9→  getRateLimitHeaders,
 10→} from '~/lib/api-keys/rate-limit';
 11→import { trackUsage } from '~/lib/api-keys/usage';
 12→import {
 13→  handleInitialize,
 14→  handleToolsCall,
 15→  handleToolsList,
 16→  type TrackingContext,
 17→} from '~/lib/mcp/handlers';
 18→
 19→export const runtime = 'nodejs';
 20→export const dynamic = 'force-dynamic';
 21→export const maxDuration = 60;
 22→
 23→const DB_TIMEOUT_MS = 10000; // 10 second timeout for database queries
 24→
 25→// Authentication is required for all MCP operations
 26→const REQUIRE_AUTH = true;
 27→
 28→interface RouteContext {
 29→  params: Promise<{ username: string; slug: string; transport: string }>;
 30→}
 31→
 32→interface JsonRpcRequest {
 33→  jsonrpc: string;
 34→  method: string;
 35→  params?: unknown;
 36→  id?: string | number;
 37→}
 38→
 39→/**
 40→ * Wrap a promise with a timeout
 41→ */
 42→function withTimeout<T>(promise: Promise<T>, ms: number, errorMessage: string): Promise<T> {
 43→  return Promise.race([
 44→    promise,
 45→    new Promise<T>((_, reject) => setTimeout(() => reject(new Error(errorMessage)), ms)),
 46→  ]);
 47→}
 48→
 49→/**
 50→ * Find a user by username
 51→ */
 52→async function getUserByUsername(username: string) {
 53→  return withTimeout(
 54→    prisma.user.findUnique({
 55→      where: { username },
 56→      select: { id: true, username: true },
 57→    }),
 58→    DB_TIMEOUT_MS,
 59→    `Database query timed out after ${DB_TIMEOUT_MS}ms`
 60→  );
 61→}
 62→
 63→/**
 64→ * Find a collection by user ID and slug or collection ID
 65→ * Supports both human-readable slugs and collection IDs for flexibility
 66→ * Returns the collection regardless of public/private status - authorization is checked separately
 67→ */
 68→async function getCollectionByUserIdAndSlugOrId(userId: string, slugOrId: string) {
 69→  return withTimeout(
 70→    prisma.collection.findFirst({
 71→      where: {
 72→        userId,
 73→        OR: [{ slug: slugOrId }, { id: slugOrId }],
 74→      },
 75→      select: { id: true, name: true, description: true, userId: true, isPublic: true },
 76→    }),
 77→    DB_TIMEOUT_MS,
 78→    `Database query timed out after ${DB_TIMEOUT_MS}ms`
 79→  );
 80→}
 81→
 82→interface JsonRpcResponse {
 83→  jsonrpc: '2.0';
 84→  id: string | number | null;
 85→  result?: unknown;
 86→  error?: { code: number; message: string };
 87→}
 88→
 89→/**
 90→ * Process a JSON-RPC request and return the response
 91→ */
 92→async function processJsonRpcRequest(
 93→  collectionId: string,
 94→  collectionName: string,
 95→  body: JsonRpcRequest,
 96→  isOwner: boolean,
 97→  trackingCtx?: TrackingContext,
 98→  headerEnvVars?: Record<string, string>
 99→): Promise<JsonRpcResponse> {
100→  const requestId = body.id ?? null;
101→
102→  switch (body.method) {
103→    case 'initialize':
104→      return handleInitialize(collectionName, requestId);
105→
106→    case 'tools/list':
107→      return await handleToolsList(collectionId, requestId);
108→
109→    case 'tools/call': {
110→      const params = body.params as {
111→        name: string;
112→        arguments?: Record<string, unknown>;
113→        env?: Record<string, string>;
114→      };
115→
116→      // For non-owners, use caller-provided env vars (or empty if not provided)
117→      // For owners, callerEnvVars is undefined so handleToolsCall uses stored env vars
118→      const callerEnvVars = isOwner ? undefined : params.env || {};
119→
120→      return await handleToolsCall(
121→        collectionId,
122→        params,
123→        requestId,
124→        callerEnvVars,
125→        trackingCtx,
126→        headerEnvVars
127→      );
128→    }
129→
130→    case 'notifications/initialized':
131→    case 'ping':
132→      return { jsonrpc: '2.0', id: requestId, result: {} };
133→
134→    default:
135→      return {
136→        jsonrpc: '2.0',
137→        id: requestId,
138→        error: { code: -32601, message: `Method not found: ${body.method}` },
139→      };
140→  }
141→}
142→
143→/**
144→ * Extract env vars from request headers.
145→ * Converts headers like `tpmjs-api-key` → `TPMJS_API_KEY`.
146→ */
147→function extractEnvVarsFromHeaders(request: NextRequest): Record<string, string> {
148→  const envVars: Record<string, string> = {};
149→  request.headers.forEach((value, key) => {
150→    if (key.startsWith('tpmjs-')) {
151→      const envKey = key.toUpperCase().replace(/-/g, '_');
152→      envVars[envKey] = value;
153→    }
154→  });
155→  return envVars;
156→}
