191→/**
192→ * POST /api/mcp/[username]/[slug]/sse
193→ * SSE transport - Server-Sent Events for streaming
194→ */
195→async function handleSseTransport(
196→  request: NextRequest,
197→  collectionId: string,
198→  collectionName: string,
199→  isOwner: boolean,
200→  trackingCtx?: TrackingContext
201→): Promise<Response> {
202→  let body: JsonRpcRequest;
203→  try {
204→    body = await request.json();
205→  } catch {
206→    return new Response(
207→      `data: ${JSON.stringify({ jsonrpc: '2.0', error: { code: -32700, message: 'Parse error' }, id: null })}\n\n`,
208→      {
209→        status: 400,
210→        headers: {
211→          'Content-Type': 'text/event-stream',
212→          'Cache-Control': 'no-cache',
213→          Connection: 'keep-alive',
214→        },
215→      }
216→    );
217→  }
218→
219→  const headerEnvVars = extractEnvVarsFromHeaders(request);
220→  const response = await processJsonRpcRequest(
221→    collectionId,
222→    collectionName,
223→    body,
224→    isOwner,
225→    trackingCtx,
226→    Object.keys(headerEnvVars).length > 0 ? headerEnvVars : undefined
227→  );
228→
229→  // For SSE, we send the response as an event and then close
230→  const encoder = new TextEncoder();
231→  const stream = new ReadableStream({
232→    start(controller) {
233→      // Send the JSON-RPC response as an SSE event
234→      const eventData = `data: ${JSON.stringify(response)}\n\n`;
235→      controller.enqueue(encoder.encode(eventData));
236→      controller.close();
237→    },
238→  });
239→
240→  return new Response(stream, {
241→    headers: {
242→      'Content-Type': 'text/event-stream',
243→      'Cache-Control': 'no-cache',
244→      Connection: 'keep-alive',
245→    },
246→  });
247→}
