249→/**
250→ * GET /api/mcp/[username]/[slug]/sse
251→ * SSE endpoint for establishing event stream connection
252→ */
253→function handleSseGet(
254→  username: string,
255→  slug: string,
256→  collectionName: string,
257→  collectionDescription: string | null
258→): Response {
259→  const encoder = new TextEncoder();
260→  const stream = new ReadableStream({
261→    start(controller) {
262→      // Send server info as initial event
263→      const serverInfo = {
264→        type: 'server_info',
265→        name: `TPMJS: ${collectionName}`,
266→        description: collectionDescription,
267→        protocol: 'mcp',
268→        transport: 'sse',
269→        endpoint: `/api/mcp/${username}/${slug}/sse`,
270→      };
271→      const eventData = `data: ${JSON.stringify(serverInfo)}\n\n`;
272→      controller.enqueue(encoder.encode(eventData));
273→      // Keep connection open for future events
274→    },
275→  });
276→
277→  return new Response(stream, {
278→    headers: {
279→      'Content-Type': 'text/event-stream',
280→      'Cache-Control': 'no-cache',
281→      Connection: 'keep-alive',
282→    },
283→  });
284→}
