  8→export const dynamic = 'force-dynamic';
  9→export const maxDuration = 60;
 10→
 11→const API_VERSION = '1.0.0';
 12→
 13→interface ApiResponse<T = unknown> {
 14→  success: boolean;
 15→  data?: T;
 16→  error?: {
 17→    code: string;
 18→    message: string;
 19→    details?: Record<string, unknown>;
 20→  };
 21→  meta: {
 22→    version: string;
 23→    timestamp: string;
 24→    requestId?: string;
 25→  };
 26→}
 27→
 28→interface RouteContext {
 29→  params: Promise<{ id: string }>;
 30→}
