 32→/**
 33→ * GET /api/collections/[id]
 34→ * Get a single collection with its tools
 35→ *
 36→ * Query params:
 37→ * - toolsLimit: Max tools to return (default: 50, max: 100)
 38→ * - toolsOffset: Offset for tools pagination (default: 0)
 39→ */
 40→export async function GET(
 41→  request: NextRequest,
 42→  context: RouteContext
 43→): Promise<NextResponse<ApiResponse>> {
 44→  const requestId = crypto.randomUUID();
 45→  const { id } = await context.params;
 46→
 47→  // Parse pagination params for tools
 48→  const { searchParams } = new URL(request.url);
 49→  const toolsLimit = Math.min(
 50→    Math.max(Number.parseInt(searchParams.get('toolsLimit') || '50', 10), 1),
 51→    100
 52→  );
 53→  const toolsOffset = Math.max(Number.parseInt(searchParams.get('toolsOffset') || '0', 10), 0);
 54→
 55→  try {
 56→    // Check authentication
 57→    const authResult = await authenticateRequest();
 58→
 59→    if (!authResult.authenticated || !authResult.userId) {
 60→      return NextResponse.json(
 61→        {
 62→          success: false,
 63→          error: { code: 'UNAUTHORIZED', message: 'Authentication required' },
 64→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
 65→        },
 66→        { status: 401 }
 67→      );
 68→    }
 69→
 70→    // Fetch collection with paginated tools
 71→    const collection = await prisma.collection.findUnique({
 72→      where: { id },
 73→      include: {
 74→        user: {
 75→          select: {
 76→            username: true,
 77→          },
 78→        },
 79→        tools: {
 80→          include: {
 81→            tool: {
 82→              include: {
 83→                package: {
 84→                  select: {
 85→                    id: true,
 86→                    npmPackageName: true,
 87→                    category: true,
 88→                  },
 89→                },
 90→              },
 91→            },
 92→          },
 93→          orderBy: { position: 'asc' },
 94→          take: toolsLimit + 1, // Fetch one extra to check hasMore
 95→          skip: toolsOffset,
 96→        },
 97→        _count: { select: { tools: true } },
 98→      },
 99→    });
100→
101→    if (!collection) {
102→      return NextResponse.json(
103→        {
104→          success: false,
105→          error: { code: 'NOT_FOUND', message: 'Collection not found' },
106→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
107→        },
108→        { status: 404 }
109→      );
110→    }
111→
112→    // Check ownership (unless collection is public)
113→    if (collection.userId !== authResult.userId && !collection.isPublic) {
114→      return NextResponse.json(
115→        {
116→          success: false,
117→          error: { code: 'FORBIDDEN', message: 'Access denied' },
118→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
119→        },
120→        { status: 403 }
121→      );
122→    }
123→
124→    // Check if there are more tools
125→    const hasMoreTools = collection.tools.length > toolsLimit;
126→    const paginatedTools = hasMoreTools ? collection.tools.slice(0, toolsLimit) : collection.tools;
127→
128→    return NextResponse.json({
129→      success: true,
130→      data: {
131→        id: collection.id,
132→        slug: collection.slug,
133→        name: collection.name,
134→        description: collection.description,
135→        isPublic: collection.isPublic,
136→        toolCount: collection._count.tools,
137→        executorType: collection.executorType,
138→        executorConfig: collection.executorConfig,
139→        envVars: collection.envVars,
140→        createdAt: collection.createdAt,
141→        updatedAt: collection.updatedAt,
142→        isOwner: collection.userId === authResult.userId,
143→        user: {
144→          username: collection.user.username,
145→        },
146→        tools: paginatedTools.map((ct) => ({
147→          id: ct.id,
148→          toolId: ct.toolId,
149→          position: ct.position,
150→          note: ct.note,
151→          addedAt: ct.addedAt,
152→          tool: {
153→            id: ct.tool.id,
154→            name: ct.tool.name,
155→            description: ct.tool.description,
156→            package: ct.tool.package,
157→          },
158→        })),
159→      },
160→      meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
161→      pagination: {
162→        toolsLimit,
163→        toolsOffset,
164→        toolsReturned: paginatedTools.length,
165→        hasMoreTools,
166→      },
167→    });
168→  } catch (error) {
169→    console.error('[API Error] GET /api/collections/[id]:', error);
170→    return NextResponse.json(
171→      {
172→        success: false,
173→        error: { code: 'INTERNAL_ERROR', message: 'Failed to fetch collection' },
174→        meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
175→      },
176→      { status: 500 }
177→    );
178→  }
179→}
