181→/**
182→ * PATCH /api/collections/[id]
183→ * Update a collection
184→ */
185→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Multiple validation checks required
186→export async function PATCH(
187→  request: NextRequest,
188→  context: RouteContext
189→): Promise<NextResponse<ApiResponse>> {
190→  const requestId = crypto.randomUUID();
191→  const { id } = await context.params;
192→
193→  try {
194→    // Check authentication
195→    const authResult = await authenticateRequest();
196→
197→    if (!authResult.authenticated || !authResult.userId) {
198→      return NextResponse.json(
199→        {
200→          success: false,
201→          error: { code: 'UNAUTHORIZED', message: 'Authentication required' },
202→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
203→        },
204→        { status: 401 }
205→      );
206→    }
207→
208→    // Check collection exists and ownership
209→    const existingCollection = await prisma.collection.findUnique({
210→      where: { id },
211→    });
212→
213→    if (!existingCollection) {
214→      return NextResponse.json(
215→        {
216→          success: false,
217→          error: { code: 'NOT_FOUND', message: 'Collection not found' },
218→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
219→        },
220→        { status: 404 }
221→      );
222→    }
223→
224→    if (existingCollection.userId !== authResult.userId) {
225→      return NextResponse.json(
226→        {
227→          success: false,
228→          error: { code: 'FORBIDDEN', message: 'Access denied' },
229→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
230→        },
231→        { status: 403 }
232→      );
233→    }
234→
235→    // Parse and validate request body
236→    const body = await request.json();
237→    const parseResult = UpdateCollectionSchema.safeParse(body);
238→
239→    if (!parseResult.success) {
240→      return NextResponse.json(
241→        {
242→          success: false,
243→          error: {
244→            code: 'VALIDATION_ERROR',
245→            message: 'Invalid request body',
246→            details: { errors: parseResult.error.flatten().fieldErrors },
247→          },
248→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
249→        },
250→        { status: 400 }
251→      );
252→    }
253→
254→    const { name, description, isPublic, executorType, executorConfig, envVars } = parseResult.data;
255→
256→    // If name is being changed, check for duplicates
257→    if (name && name !== existingCollection.name) {
258→      const duplicateName = await prisma.collection.findFirst({
259→        where: {
260→          userId: authResult.userId,
261→          name: { equals: name, mode: 'insensitive' },
262→          id: { not: id },
263→        },
264→      });
265→
266→      if (duplicateName) {
267→        return NextResponse.json(
268→          {
269→            success: false,
270→            error: {
271→              code: 'DUPLICATE_NAME',
272→              message: 'A collection with this name already exists',
273→            },
274→            meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
275→          },
276→          { status: 409 }
277→        );
278→      }
279→    }
280→
281→    // Update collection (transform null to Prisma.JsonNull for JSON fields)
282→    const collection = await prisma.collection.update({
283→      where: { id },
284→      data: {
285→        ...(name !== undefined && { name }),
286→        ...(description !== undefined && { description }),
287→        ...(isPublic !== undefined && { isPublic }),
288→        ...(executorType !== undefined && { executorType }),
289→        ...(executorConfig !== undefined && {
290→          executorConfig: executorConfig === null ? Prisma.JsonNull : executorConfig,
291→        }),
292→        ...(envVars !== undefined && {
293→          envVars: envVars === null ? Prisma.JsonNull : envVars,
294→        }),
295→      },
296→      include: {
297→        _count: { select: { tools: true } },
298→      },
299→    });
300→
301→    // Log activity (fire-and-forget)
302→    if (envVars !== undefined) {
303→      logActivity({
304→        userId: authResult.userId,
305→        type: 'COLLECTION_ENV_UPDATED',
306→        targetName: collection.name,
307→        targetType: 'collection',
308→        collectionId: collection.id,
309→      });
310→    } else {
311→      logActivity({
312→        userId: authResult.userId,
313→        type: 'COLLECTION_UPDATED',
314→        targetName: collection.name,
315→        targetType: 'collection',
316→        collectionId: collection.id,
317→      });
318→    }
319→
320→    return NextResponse.json({
321→      success: true,
322→      data: {
323→        id: collection.id,
324→        name: collection.name,
325→        description: collection.description,
326→        isPublic: collection.isPublic,
327→        toolCount: collection._count.tools,
328→        executorType: collection.executorType,
329→        executorConfig: collection.executorConfig,
330→        envVars: collection.envVars,
331→        createdAt: collection.createdAt,
332→        updatedAt: collection.updatedAt,
333→      },
334→      meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
335→    });
336→  } catch (error) {
337→    console.error('[API Error] PATCH /api/collections/[id]:', error);
338→    return NextResponse.json(
339→      {
340→        success: false,
341→        error: { code: 'INTERNAL_ERROR', message: 'Failed to update collection' },
342→        meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
343→      },
344→      { status: 500 }
345→    );
346→  }
347→}
