  1→import { createServer } from 'node:http';
  2→import { URL } from 'node:url';
  3→import { Args, Command, Flags } from '@oclif/core';
  4→import open from 'open';
  5→import { TpmClient } from '../../lib/api-client.js';
  6→import { getApiUrl, saveCredentials } from '../../lib/config.js';
  7→import { createOutput } from '../../lib/output.js';
  8→
  9→export default class Login extends Command {
 10→  static description = 'Authenticate with TPMJS';
 11→
 12→  static examples = [
 13→    '<%= config.bin %> <%= command.id %> --api-key tpm_xxxxx',
 14→    '<%= config.bin %> <%= command.id %> --browser',
 15→  ];
 16→
 17→  static flags = {
 18→    'api-key': Flags.string({
 19→      char: 'k',
 20→      description: 'API key (or set TPMJS_API_KEY environment variable)',
 21→    }),
 22→    browser: Flags.boolean({
 23→      char: 'b',
 24→      description: 'Open browser for OAuth authentication',
 25→      default: false,
 26→    }),
 27→    json: Flags.boolean({
 28→      description: 'Output in JSON format',
 29→      default: false,
 30→    }),
 31→    verbose: Flags.boolean({
 32→      char: 'v',
 33→      description: 'Show verbose output',
 34→      default: false,
 35→    }),
 36→  };
 37→
 38→  static args = {
 39→    key: Args.string({
 40→      description: 'API key (alternative to --api-key flag)',
 41→      required: false,
 42→    }),
 43→  };
 44→
 45→  async run(): Promise<void> {
 46→    const { args, flags } = await this.parse(Login);
 47→    const output = createOutput(flags);
 48→
 49→    const apiKey = flags['api-key'] ?? args.key;
 50→
 51→    if (apiKey) {
 52→      // Direct API key authentication
 53→      await this.loginWithApiKey(apiKey, output, flags);
 54→    } else if (flags.browser) {
 55→      // Browser OAuth flow
 56→      await this.loginWithBrowser(output, flags);
 57→    } else {
 58→      // Prompt for API key
 59→      output.info('No API key provided. Use --api-key or --browser flag.');
 60→      output.newLine();
 61→      output.text('Options:');
 62→      output.listItem('tpm auth login --api-key <your-api-key>');
 63→      output.listItem('tpm auth login --browser (opens browser for OAuth)');
 64→      output.newLine();
 65→      output.text(
 66→        `Get your API key at: ${output.link('tpmjs.com/dashboard/settings/tpmjs-api-keys', 'https://tpmjs.com/dashboard/settings/tpmjs-api-keys')}`
 67→      );
 68→    }
 69→  }
 70→
 71→  private async loginWithApiKey(
 72→    apiKey: string,
 73→    output: ReturnType<typeof createOutput>,
 74→    flags: { json?: boolean; verbose?: boolean }
 75→  ): Promise<void> {
 76→    const spinner = output.spinner('Validating API key...');
 77→
 78→    try {
 79→      // Test the API key
 80→      const client = new TpmClient({ apiKey });
 81→      const response = await client.whoami();
 82→
 83→      if (!response.success || !response.data) {
 84→        spinner.fail('Invalid API key');
 85→        return;
 86→      }
 87→
 88→      // Save credentials
 89→      saveCredentials({ apiKey });
 90→      spinner.succeed('Logged in successfully');
 91→
 92→      if (flags.json) {
 93→        output.json({
 94→          success: true,
 95→          user: response.data,
 96→        });
 97→      } else {
 98→        output.newLine();
 99→        output.keyValue('Email', response.data.email);
100→        if (response.data.username) {
101→          output.keyValue('Username', response.data.username);
102→        }
103→        if (response.data.name) {
104→          output.keyValue('Name', response.data.name);
105→        }
106→      }
107→    } catch (error) {
108→      spinner.fail('Authentication failed');
109→      output.error(
110→        error instanceof Error ? error.message : 'Unknown error',
111→        flags.verbose ? String(error) : undefined
112→      );
113→    }
114→  }
115→
116→  private async loginWithBrowser(
117→    output: ReturnType<typeof createOutput>,
118→    flags: { json?: boolean; verbose?: boolean }
119→  ): Promise<void> {
120→    const port = 9876;
121→    const callbackUrl = `http://localhost:${port}/callback`;
122→    const state = crypto.randomUUID();
123→
124→    output.info('Opening browser for authentication...');
125→
126→    return new Promise((resolve) => {
127→      let timeoutId: NodeJS.Timeout;
128→
129→      const cleanup = () => {
130→        clearTimeout(timeoutId);
131→        server.close();
132→      };
133→
134→      const server = createServer(async (req, res) => {
135→        const url = new URL(req.url ?? '/', `http://localhost:${port}`);
136→
137→        if (url.pathname === '/callback') {
138→          const receivedState = url.searchParams.get('state');
139→          const apiKey = url.searchParams.get('key');
140→          const error = url.searchParams.get('error');
141→
142→          if (error) {
143→            res.writeHead(200, { 'Content-Type': 'text/html' });
144→            res.end(
145→              '<html><body><h1>Authentication Failed</h1><p>You can close this window.</p></body></html>'
146→            );
147→            cleanup();
148→            output.error(`Authentication failed: ${error}`);
149→            resolve();
150→            return;
151→          }
152→
153→          if (receivedState !== state) {
154→            res.writeHead(200, { 'Content-Type': 'text/html' });
155→            res.end(
156→              '<html><body><h1>Invalid State</h1><p>Authentication failed due to invalid state.</p></body></html>'
157→            );
158→            cleanup();
159→            output.error('Authentication failed: Invalid state parameter');
160→            resolve();
161→            return;
162→          }
163→
164→          if (apiKey) {
165→            saveCredentials({ apiKey });
166→
167→            res.writeHead(200, { 'Content-Type': 'text/html' });
168→            res.end(
169→              '<html><body><h1>Success!</h1><p>You are now logged in. You can close this window.</p></body></html>'
170→            );
171→            cleanup();
172→
173→            output.success('Logged in successfully via browser');
174→
175→            if (flags.json) {
176→              output.json({ success: true });
177→            }
178→
179→            resolve();
180→          } else {
181→            res.writeHead(200, { 'Content-Type': 'text/html' });
182→            res.end('<html><body><h1>Error</h1><p>No API key received.</p></body></html>');
183→            cleanup();
184→            output.error('No API key received from authentication');
185→            resolve();
186→          }
187→        } else {
188→          res.writeHead(404);
189→          res.end('Not found');
190→        }
191→      });
192→
193→      server.listen(port, async () => {
194→        const authUrl = `${getApiUrl().replace('/api', '')}/cli/auth?state=${state}&callback=${encodeURIComponent(callbackUrl)}`;
195→
196→        output.debug(`Auth URL: ${authUrl}`);
197→        output.text('Waiting for authentication...');
198→
199→        try {
200→          await open(authUrl);
201→        } catch {
202→          output.warning('Could not open browser automatically.');
203→          output.text(`Please open this URL manually: ${authUrl}`);
204→        }
205→      });
206→
207→      // Timeout after 5 minutes
208→      timeoutId = setTimeout(
209→        () => {
210→          server.close();
211→          output.error('Authentication timed out');
212→          resolve();
213→        },
214→        5 * 60 * 1000
215→      );
216→    });
217→  }
218→}
