 72→          },
 73→          bridgeTools: true,
 74→          customTools: {
 75→            include: { server: true },
 76→          },
 77→          user: {
 78→            include: {
 79→              bridgeConnection: true,
 80→            },
 81→          },
 82→        },
 83→      }),
 84→      DB_TIMEOUT_MS,
 85→      'Database query timed out'
 86→    );
 87→
 88→    // Convert registry tools to MCP format
 89→    const registryTools = collection?.tools.map((ct) => convertToMcpTool(ct.tool)) ?? [];
 90→
 91→    // Convert bridge tools to MCP format
 92→    const bridgeTools: ReturnType<typeof convertBridgeToolToMcp>[] = [];
 93→
 94→    if (collection?.bridgeTools.length && collection.user.bridgeConnection) {
 95→      const bridgeConnection = collection.user.bridgeConnection;
 96→      const availableBridgeTools = (bridgeConnection.tools as unknown as BridgeTool[]) || [];
 97→
 98→      // Only include bridge tools if bridge is connected
 99→      if (bridgeConnection.status === 'connected') {
100→        for (const collectionBridgeTool of collection.bridgeTools) {
101→          // Find the tool definition from the bridge connection
102→          const bridgeTool = availableBridgeTools.find(
103→            (bt) =>
104→              bt.serverId === collectionBridgeTool.serverId &&
105→              bt.name === collectionBridgeTool.toolName
106→          );
107→
108→          if (bridgeTool) {
109→            bridgeTools.push(convertBridgeToolToMcp(bridgeTool, collectionBridgeTool.displayName));
110→          }
111→        }
112→      }
113→    }
114→
115→    // Convert custom MCP server tools to MCP format
116→    // Uses cached tool definitions so they appear even if the remote server is temporarily down
117→    const customTools: ReturnType<typeof convertCustomToolToMcp>[] = [];
118→
119→    if (collection?.customTools.length) {
120→      for (const ct of collection.customTools) {
121→        if (ct.server.status !== 'synced') continue;
122→
123→        const cachedTools = (ct.server.tools as unknown as CustomMcpTool[]) || [];
124→        const toolDef = cachedTools.find((t) => t.name === ct.toolName);
125→
126→        if (toolDef) {
127→          customTools.push(
128→            convertCustomToolToMcp(
129→              { ...toolDef, serverId: ct.serverId, serverName: ct.server.name },
130→              ct.displayName
131→            )
132→          );
133→        }
134→      }
135→    }
136→
137→    return {
138→      jsonrpc: '2.0',
139→      id: requestId,
140→      result: { tools: [...registryTools, ...bridgeTools, ...customTools] },
141→    };
142→  } catch (error) {
143→    console.error('[MCP tools/list] Error:', error);
144→    return {
145→      jsonrpc: '2.0',
146→      id: requestId,
147→      error: { code: -32603, message: error instanceof Error ? error.message : 'Internal error' },
148→    };
149→  }
150→}
