165→/**
166→ * Handle MCP tools/call request
167→ * @param callerEnvVars - Optional env vars from caller (non-owner accessing public collection)
168→ *                        When provided, these are used INSTEAD of collection's stored env vars
169→ * @param trackingCtx - Optional tracking context for execution event tracking
170→ * @param headerEnvVars - Optional env vars extracted from request headers (e.g. tpmjs-api-key → TPMJS_API_KEY)
171→ */
172→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: MCP tool execution with env resolution, tracking, and error handling
173→export async function handleToolsCall(
174→  collectionId: string,
175→  params: ToolsCallParams,
176→  requestId: JsonRpcId,
177→  callerEnvVars?: Record<string, string>,
178→  trackingCtx?: TrackingContext,
179→  headerEnvVars?: Record<string, string>
180→): Promise<JsonRpcResponse> {
181→  try {
182→    const parsed = parseToolName(params.name);
183→    if (!parsed) {
184→      return {
185→        jsonrpc: '2.0',
186→        id: requestId,
187→        error: { code: -32602, message: `Invalid tool name: ${params.name}` },
188→      };
189→    }
190→
191→    // Handle custom MCP server tool calls
192→    if (parsed.type === 'custom') {
193→      return handleCustomToolCall(
194→        collectionId,
195→        parsed.serverId,
196→        parsed.toolName,
197→        params.arguments ?? {},
198→        requestId
199→      );
200→    }
201→
202→    // Handle bridge tool calls
203→    if (parsed.type === 'bridge') {
204→      return handleBridgeToolCall(
205→        collectionId,
206→        parsed.serverId,
207→        parsed.toolName,
208→        params.arguments ?? {},
209→        requestId
210→      );
211→    }
212→
213→    // Handle registry tool calls
214→    // Verify tool exists in collection and get executor config
215→    const collection = await withTimeout(
216→      prisma.collection.findUnique({
217→        where: { id: collectionId },
218→        select: {
219→          executorType: true,
220→          executorConfig: true,
221→          envVars: true,
222→          tools: {
223→            include: { tool: { include: { package: true } } },
224→          },
225→        },
226→      }),
227→      DB_TIMEOUT_MS,
228→      'Database query timed out'
229→    );
230→
231→    // Try all possible package name and tool name combinations
232→    // This handles both old format (full package name) and new shortened format
233→    type CollectionTool = NonNullable<typeof collection>['tools'][number];
234→    let collectionTool: CollectionTool | undefined;
235→
236→    for (const pkgName of parsed.possiblePackages) {
237→      for (const toolName of parsed.possibleToolNames) {
238→        collectionTool = collection?.tools.find(
239→          (ct) => ct.tool.package.npmPackageName === pkgName && ct.tool.name === toolName
240→        );
241→        if (collectionTool) break;
242→      }
243→      if (collectionTool) break;
244→    }
245→
246→    if (!collectionTool) {
247→      return {
248→        jsonrpc: '2.0',
249→        id: requestId,
250→        error: { code: -32602, message: `Tool not found in collection: ${params.name}` },
251→      };
252→    }
253→
254→    // Get the actual package name and version that matched
255→    const actualPackageName = collectionTool.tool.package.npmPackageName;
256→    const actualVersion = collectionTool.tool.package.npmVersion;
257→
258→    // When caller provides env vars (non-owner), validate required env vars
259→    if (callerEnvVars !== undefined) {
260→      const packageEnv = collectionTool.tool.package.env as TpmjsEnv[] | null;
261→      if (packageEnv && Array.isArray(packageEnv)) {
262→        const missingVars = packageEnv.filter(
263→          (env) => env.required !== false && !env.default && !callerEnvVars[env.name]
264→        );
265→
266→        if (missingVars.length > 0) {
267→          return {
268→            jsonrpc: '2.0',
269→            id: requestId,
270→            error: {
271→              code: -32602,
272→              message: 'Missing required environment variables',
273→              data: {
274→                missingVars: missingVars.map((e) => ({
275→                  name: e.name,
276→                  description: e.description,
277→                })),
278→              },
279→            },
280→          };
281→        }
282→      }
283→    }
284→
285→    // Resolve executor configuration (collection config only for MCP - no agent context)
286→    const executorConfig = parseExecutorConfig(
287→      collection?.executorType,
288→      collection?.executorConfig
289→    );
290→
291→    // Execute via resolved executor
292→    // Use caller-provided env vars if given (non-owner), otherwise use collection's stored env vars
293→    // Merge in any env vars extracted from request headers (e.g. tpmjs-api-key → TPMJS_API_KEY)
294→    const effectiveEnvVars = {
295→      ...(callerEnvVars ?? (collection?.envVars as Record<string, string>) ?? {}),
296→      ...headerEnvVars,
297→    };
298→    // Pass explicit version to avoid Deno HTTP import cache issues with @latest
299→    // Use actual tool name from DB, not parsed name (which may have wrong suffix)
300→    const execStart = Date.now();
301→    const result = await executeWithExecutor(executorConfig, {
302→      packageName: actualPackageName,
303→      name: collectionTool.tool.name,
304→      version: actualVersion,
305→      params: params.arguments ?? {},
306→      env: Object.keys(effectiveEnvVars).length > 0 ? effectiveEnvVars : undefined,
307→    });
308→    const execDurationMs = Date.now() - execStart;
309→
310→    // Track execution event (fire-and-forget)
311→    if (trackingCtx) {
312→      trackExecution({
313→        eventType: 'tool_call',
314→        source: trackingCtx.source,
315→        userId: trackingCtx.userId,
316→        apiKeyId: trackingCtx.apiKeyId,
317→        toolId: collectionTool.tool.id,
318→        collectionId: trackingCtx.collectionId ?? collectionId,
319→        toolName: collectionTool.tool.name,
320→        packageName: actualPackageName,
321→        status: result.success ? 'success' : 'error',
322→        durationMs: execDurationMs,
323→        errorMessage: result.success ? undefined : String(result.error),
324→        // ML training data
325→        inputArgs: params.arguments,
326→        outputSummary: result.success ? result.output : { error: result.error },
327→      });
328→
329→      // Log user-facing activity (fire-and-forget)
330→      if (trackingCtx.userId) {
331→        logActivity({
332→          userId: trackingCtx.userId,
333→          type: 'TOOL_EXECUTED',
334→          targetName: collectionTool.tool.name,
335→          targetType: 'tool',
336→          toolId: collectionTool.tool.id,
337→          collectionId: trackingCtx.collectionId ?? collectionId,
338→          metadata: {
339→            source: trackingCtx.source,
340→            status: result.success ? 'success' : 'error',
341→            packageName: actualPackageName,
342→          },
343→        });
344→      }
345→    }
346→
347→    if (!result.success) {
348→      return {
349→        jsonrpc: '2.0',
350→        id: requestId,
351→        result: {
352→          content: [{ type: 'text', text: `Error: ${result.error}` }],
353→          isError: true,
354→        },
355→      };
356→    }
357→
358→    return {
359→      jsonrpc: '2.0',
360→      id: requestId,
361→      result: {
362→        content: [
363→          {
364→            type: 'text',
365→            text:
366→              typeof result.output === 'string'
367→                ? result.output
368→                : JSON.stringify(result.output, null, 2),
369→          },
370→        ],
371→      },
372→    };
373→  } catch (error) {
374→    console.error('[MCP tools/call] Error:', error);
375→    return {
376→      jsonrpc: '2.0',
377→      id: requestId,
378→      error: { code: -32603, message: error instanceof Error ? error.message : 'Internal error' },
379→    };
380→  }
381→}
