383→/**
384→ * Handle a bridge tool call by routing it through the user's bridge connection
385→ */
386→async function handleBridgeToolCall(
387→  collectionId: string,
388→  serverId: string,
389→  toolName: string,
390→  args: Record<string, unknown>,
391→  requestId: JsonRpcId
392→): Promise<JsonRpcResponse> {
393→  try {
394→    // Get the collection's owner and their bridge connection
395→    const collection = await withTimeout(
396→      prisma.collection.findUnique({
397→        where: { id: collectionId },
398→        include: {
399→          bridgeTools: {
400→            where: { serverId, toolName },
401→          },
402→          user: {
403→            include: { bridgeConnection: true },
404→          },
405→        },
406→      }),
407→      DB_TIMEOUT_MS,
408→      'Database query timed out'
409→    );
410→
411→    if (!collection) {
412→      return {
413→        jsonrpc: '2.0',
414→        id: requestId,
415→        error: { code: -32602, message: 'Collection not found' },
416→      };
417→    }
418→
419→    // Verify the bridge tool exists in the collection
420→    const bridgeTool = collection.bridgeTools[0];
421→    if (!bridgeTool) {
422→      return {
423→        jsonrpc: '2.0',
424→        id: requestId,
425→        error: {
426→          code: -32602,
427→          message: `Bridge tool not found in collection: ${serverId}/${toolName}`,
428→        },
429→      };
430→    }
431→
432→    // Verify the user has an active bridge connection
433→    const bridgeConnection = collection.user.bridgeConnection;
434→    if (!bridgeConnection || bridgeConnection.status !== 'connected') {
435→      return {
436→        jsonrpc: '2.0',
437→        id: requestId,
438→        result: {
439→          content: [
440→            {
441→              type: 'text',
442→              text: 'Error: Bridge is not connected. Start the bridge CLI to use bridge tools.',
443→            },
444→          ],
445→          isError: true,
446→        },
447→      };
448→    }
449→
450→    // Check if the bridge is stale (not seen in 2 minutes)
451→    if (bridgeConnection.lastSeen) {
452→      const staleThreshold = 2 * 60 * 1000; // 2 minutes
453→      if (Date.now() - bridgeConnection.lastSeen.getTime() > staleThreshold) {
454→        return {
455→          jsonrpc: '2.0',
456→          id: requestId,
457→          result: {
458→            content: [
459→              {
460→                type: 'text',
461→                text: 'Error: Bridge connection appears stale. Please check if the bridge CLI is running.',
462→              },
463→            ],
464→            isError: true,
465→          },
466→        };
467→      }
468→    }
469→
470→    // Generate a unique call ID
471→    const callId = `${Date.now()}-${Math.random().toString(36).slice(2, 11)}`;
472→
473→    // Queue the tool call for the bridge to pick up
474→    queueBridgeToolCall(collection.user.id, callId, serverId, toolName, args);
475→
476→    // Wait for the result (with 5 minute timeout)
477→    const result = await waitForBridgeResult(callId, 300000);
478→
479→    if (result.error) {
480→      return {
481→        jsonrpc: '2.0',
482→        id: requestId,
483→        result: {
484→          content: [{ type: 'text', text: `Error: ${result.error.message}` }],
485→          isError: true,
486→        },
487→      };
488→    }
489→
490→    // Format the result
491→    const content = result.result as { content?: unknown[]; isError?: boolean } | undefined;
492→    if (content?.content) {
493→      return {
494→        jsonrpc: '2.0',
495→        id: requestId,
496→        result: {
497→          content: content.content,
498→          isError: content.isError,
499→        },
500→      };
501→    }
502→
503→    return {
504→      jsonrpc: '2.0',
505→      id: requestId,
506→      result: {
507→        content: [
508→          {
509→            type: 'text',
510→            text:
511→              typeof result.result === 'string'
512→                ? result.result
513→                : JSON.stringify(result.result, null, 2),
514→          },
515→        ],
516→      },
517→    };
518→  } catch (error) {
519→    console.error('[MCP bridge tool call] Error:', error);
520→    return {
521→      jsonrpc: '2.0',
522→      id: requestId,
523→      error: { code: -32603, message: error instanceof Error ? error.message : 'Internal error' },
524→    };
525→  }
526→}
