257→/**
258→ * Custom MCP tool definition from a remote server's cached tools
259→ */
260→export interface CustomMcpTool {
261→  serverId: string;
262→  serverName: string;
263→  name: string;
264→  description?: string;
265→  inputSchema?: Record<string, unknown>;
266→}
267→
268→/**
269→ * Create MCP name for a custom remote server tool
270→ * Example: clxyz123 + get_weather → custom--clxyz123--get_weather
271→ */
272→export function sanitizeCustomToolName(serverId: string, toolName: string): string {
273→  const sanitizedServer = serverId.replace(/[^a-zA-Z0-9_-]/g, '-');
274→  const sanitizedTool = toolName.replace(/[^a-zA-Z0-9_-]/g, '-');
275→  return `custom--${sanitizedServer}--${sanitizedTool}`;
276→}
