278→/**
279→ * Convert a custom MCP tool definition to an MCP tool definition.
280→ * Sanitizes inputSchema to ensure it conforms to Claude's JSON Schema subset.
281→ */
282→export function convertCustomToolToMcp(
283→  tool: CustomMcpTool,
284→  displayName?: string | null
285→): McpToolDefinition {
286→  return {
287→    name: sanitizeCustomToolName(tool.serverId, tool.name),
288→    description: displayName
289→      ? `[${tool.serverName}] ${displayName}`
290→      : tool.description || `${tool.name} from ${tool.serverName}`,
291→    inputSchema: sanitizeInputSchema(tool.inputSchema),
292→  };
293→}
