295→/**
296→ * Parsed tool name result - either a registry tool, bridge tool, or custom tool
297→ */
298→export type ParsedToolName =
299→  | {
300→      type: 'registry';
301→      packageName: string;
302→      literalPackageName: string;
303→      toolName: string;
304→      possiblePackages: string[];
305→      possibleToolNames: string[];
306→    }
307→  | { type: 'bridge'; serverId: string; toolName: string }
308→  | { type: 'custom'; serverId: string; toolName: string };
309→
310→/**
311→ * Parse an MCP tool name back into its components.
312→ * Handles both registry tools and bridge tools.
313→ *
314→ * Registry: tpmjs-hello--helloWorldTool → { type: 'registry', packageName: "@tpmjs/hello", toolName: "helloWorldTool" }
315→ * Shortened: sprites-get--spritesGet → tries @tpmjs/tools-sprites-get, @tpmjs/sprites-get, sprites-get
316→ * Bridge: bridge--chrome-devtools--screenshot → { type: 'bridge', serverId: "chrome-devtools", toolName: "screenshot" }
317→ */
318→export function parseToolName(mcpName: string): ParsedToolName | null {
319→  // Check if it's a custom remote MCP server tool
320→  const customMatch = mcpName.match(/^custom--([^-]+(?:-[^-]+)*)--(.+)$/);
321→  if (customMatch?.[1] && customMatch[2]) {
322→    return {
323→      type: 'custom',
324→      serverId: customMatch[1],
325→      toolName: customMatch[2],
326→    };
327→  }
328→
329→  // Check if it's a bridge tool
330→  const bridgeMatch = mcpName.match(/^bridge--([^-]+(?:-[^-]+)*)--(.+)$/);
331→  if (bridgeMatch?.[1] && bridgeMatch[2]) {
332→    return {
333→      type: 'bridge',
334→      serverId: bridgeMatch[1],
335→      toolName: bridgeMatch[2],
336→    };
337→  }
338→
339→  // Otherwise parse as registry tool
340→  const match = mcpName.match(/^(.+)--(.+)$/);
341→  if (!match || !match[1] || !match[2]) return null;
342→
343→  const pkg = match[1];
344→  const toolName = match[2];
345→
346→  // Add back 'Tool' suffix if it was removed (try both with and without)
347→  // The handler will try to find the tool with both variants
348→  const toolNameWithSuffix = toolName.endsWith('Tool') ? toolName : `${toolName}Tool`;
349→
350→  // Generate possible package names to try:
351→  // 1. @tpmjs/tools-{pkg} (shortened tpmjs-tools- prefix)
352→  // 2. @tpmjs/{pkg} (shortened tpmjs- prefix)
353→  // 3. All @{scope}/{name} splits (try every dash as the scope/name boundary)
354→  //    e.g. "perplexity-ai-ai-sdk" → @perplexity/ai-ai-sdk, @perplexity-ai/ai-sdk, @perplexity-ai-ai/sdk
355→  // 4. {pkg} as literal (non-scoped packages)
356→  const possiblePackages = [`@tpmjs/tools-${pkg}`, `@tpmjs/${pkg}`];
357→
358→  // Try every dash position as the scope/name boundary for scoped packages
359→  const dashPositions = [...pkg.matchAll(/-/g)].map((m) => m.index);
360→  for (const pos of dashPositions) {
361→    possiblePackages.push(`@${pkg.slice(0, pos)}/${pkg.slice(pos + 1)}`);
362→  }
363→
364→  possiblePackages.push(pkg);
365→
366→  // Return the first scoped interpretation as primary, with literal as fallback
367→  return {
368→    type: 'registry',
369→    packageName: possiblePackages[0]!, // @tpmjs/tools-{pkg}
370→    literalPackageName: pkg,
371→    toolName: toolNameWithSuffix,
372→    // Additional candidates for the handler to try
373→    possiblePackages,
374→    possibleToolNames: [toolNameWithSuffix, toolName],
375→  } as ParsedToolName;
376→}
377→
378→/**
379→ * Convert a bridge tool definition to an MCP tool definition.
380→ * Sanitizes inputSchema to ensure it conforms to Claude's JSON Schema subset.
381→ */
382→export function convertBridgeToolToMcp(
383→  tool: BridgeTool,
384→  displayName?: string | null
385→): McpToolDefinition {
386→  return {
387→    name: sanitizeBridgeToolName(tool.serverId, tool.name),
388→    description: displayName
389→      ? `[${tool.serverName}] ${displayName}`
390→      : tool.description || `${tool.name} from ${tool.serverName}`,
391→    inputSchema: sanitizeInputSchema(tool.inputSchema),
392→  };
393→}
