 14→interface ApiResponse<T = unknown> {
 15→  success: boolean;
 16→  data?: T;
 17→  error?: {
 18→    code: string;
 19→    message: string;
 20→    details?: Record<string, unknown>;
 21→  };
 22→  meta: {
 23→    version: string;
 24→    timestamp: string;
 25→    requestId?: string;
 26→  };
