import { prisma } from '@tpmjs/db';
import { Badge } from '@tpmjs/ui/Badge/Badge';
import { Button } from '@tpmjs/ui/Button/Button';
import { Container } from '@tpmjs/ui/Container/Container';
import { Icon } from '@tpmjs/ui/Icon/Icon';
import Link from 'next/link';
import { AppHeader } from '../components/AppHeader';
import { EcosystemStats } from '../components/home/EcosystemStats';
import { FeaturesSection } from '../components/home/FeaturesSection';
import { HeroSection } from '../components/home/HeroSection';
import { McpSection } from '../components/home/McpSection';

export const dynamic = 'force-dynamic';

async function getHomePageData() {
  try {
    // Fetch stats in parallel
    const [
      packageCount,
      toolCount,
      featuredTools,
      categoryStats,
      featuredScenarios,
      latestSnapshot,
    ] = await Promise.all([
      // Total package count
      prisma.package.count(),

      // Total tool count
      prisma.tool.count(),

      // Top 6 featured tools by quality score
      prisma.tool.findMany({
        orderBy: [{ qualityScore: 'desc' }, { package: { npmDownloadsLastMonth: 'desc' } }],
        take: 6,
        select: {
          id: true,
          name: true,
          description: true,
          qualityScore: true,
          likeCount: true,
          package: {
            select: {
              npmPackageName: true,
              category: true,
              npmDownloadsLastMonth: true,
              isOfficial: true,
            },
          },
        },
      }),

      // Category distribution for stats (group by package category)
      prisma.package.groupBy({
        by: ['category'],
        _count: {
          _all: true,
        },
      }),

      // Featured scenarios - mix of high quality, diverse, and fresh
      (async () => {
        // Get high quality scenarios
        const highQuality = await prisma.scenario.findMany({
          where: {
            collection: { isPublic: true },
            qualityScore: { gte: 0.3 },
            totalRuns: { gte: 1 },
          },
          orderBy: { qualityScore: 'desc' },
          take: 3,
          include: {
            collection: {
              select: {
                id: true,
                name: true,
                slug: true,
                user: { select: { username: true } },
              },
            },
          },
        });

        // Get fresh scenarios (excluding already selected)
        const seenIds = new Set(highQuality.map((s) => s.id));
        const fresh = await prisma.scenario.findMany({
          where: {
            collection: { isPublic: true },
            id: { notIn: Array.from(seenIds) },
          },
          orderBy: { createdAt: 'desc' },
          take: 3,
          include: {
            collection: {
              select: {
                id: true,
                name: true,
                slug: true,
                user: { select: { username: true } },
              },
            },
          },
        });

        return [...highQuality, ...fresh].slice(0, 6);
      })(),

      // Latest stats snapshot (pre-computed daily)
      prisma.statsSnapshot.findFirst({
        orderBy: { date: 'desc' },
        select: {
          totalTools: true,
          totalPackages: true,
          totalNpmDownloads: true,
          totalGithubStars: true,
          executionsTotal: true,
          executionsAvgTimeMs: true,
          activeDevs7d: true,
          totalSimulations: true,
          categories: true,
        },
      }),
    ]);

    // Always query all-time avg execution time (snapshot only has daily value)
    // If no snapshot, also query other live data as fallback
    let ecosystemStats: {
      publishedTools: number;
      activeDevelopers: number;
      totalExecutions: number;
      avgResponseMs: number | null;
      totalDownloads: number;
    };

    if (latestSnapshot) {
      const avgExecTime = await prisma.simulation.aggregate({
        where: { status: 'success', executionTimeMs: { not: null } },
        _avg: { executionTimeMs: true },
      });

      ecosystemStats = {
        publishedTools: latestSnapshot.totalTools,
        activeDevelopers: latestSnapshot.activeDevs7d,
        totalExecutions: latestSnapshot.totalSimulations,
        avgResponseMs: avgExecTime._avg.executionTimeMs
          ? Math.round(avgExecTime._avg.executionTimeMs)
          : null,
        totalDownloads: latestSnapshot.totalNpmDownloads,
      };
    } else {
      // No snapshot — query live data directly
      const [activeDevsResult, totalSimulations, avgExecTime, npmDownloads] = await Promise.all([
        prisma.userActivity
          .groupBy({
            by: ['userId'],
            where: {
              createdAt: { gte: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000) },
            },
          })
          .then((r) => r.length),
        prisma.simulation.count(),
        prisma.simulation.aggregate({
          where: { status: 'success', executionTimeMs: { not: null } },
          _avg: { executionTimeMs: true },
        }),
        prisma.package.aggregate({ _sum: { npmDownloadsLastMonth: true } }),
      ]);

      ecosystemStats = {
        publishedTools: toolCount,
        activeDevelopers: activeDevsResult,
        totalExecutions: totalSimulations,
        avgResponseMs: avgExecTime._avg.executionTimeMs
          ? Math.round(avgExecTime._avg.executionTimeMs)
          : null,
        totalDownloads: npmDownloads._sum.npmDownloadsLastMonth ?? 0,
      };
    }

    return {
      stats: {
        packageCount,
        toolCount,
        categoryCount: categoryStats.length,
        totalDownloads: latestSnapshot?.totalNpmDownloads ?? ecosystemStats.totalDownloads,
        totalStars: latestSnapshot?.totalGithubStars ?? 0,
      },
      ecosystemStats,
      featuredTools,
      categories: categoryStats.slice(0, 5).map((c) => ({
        name: c.category,
        count: c._count._all,
      })),
      featuredScenarios,
    };
  } catch (error) {
    console.error('Failed to fetch homepage data:', error);
    return {
      stats: {
        packageCount: 0,
        toolCount: 0,
        categoryCount: 0,
        totalDownloads: 0,
        totalStars: 0,
      },
      ecosystemStats: {
        publishedTools: 0,
        activeDevelopers: 0,
        totalExecutions: 0,
        avgResponseMs: null,
        totalDownloads: 0,
      },
      featuredTools: [],
      categories: [],
      featuredScenarios: [],
    };
  }
}

export default async function HomePage(): Promise<React.ReactElement> {
  const data = await getHomePageData();
  return (
    <>
      <AppHeader />

      <main>
        {/* Hero Section - Dithered Design */}
        <HeroSection stats={data.stats} />

        {/* Ecosystem Stats */}
        <EcosystemStats stats={data.ecosystemStats} />

        {/* Features Section */}
        <FeaturesSection toolCount={data.stats.toolCount} />

        {/* Architecture Diagram Section - temporarily disabled
        <section className="py-16 bg-background border-b border-border">
          <Container size="xl" padding="lg">
            <div className="text-center mb-10">
              <h2 className="text-3xl md:text-4xl font-bold mb-4 text-foreground">
                How It Works
              </h2>
              <p className="text-lg text-foreground-secondary max-w-2xl mx-auto">
                Publish once to npm, reach every AI agent. Your tool goes live in minutes.
              </p>
            </div>
            <ArchitectureDiagramWrapper />
          </Container>
        </section>
        */}

        {/* Featured Tools Section */}
        <section className="py-16 bg-background">
          <Container size="xl" padding="lg">
            <div className="text-center mb-12">
              <h2 className="text-3xl md:text-4xl font-bold mb-4 text-foreground">
                Featured Tools
              </h2>
              <p className="text-lg text-foreground-secondary max-w-2xl mx-auto mb-8">
                Production-ready tools you can use today. Add to your AI agent in one line.
              </p>
            </div>

            {data.featuredTools.length > 0 ? (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 md:gap-6 mb-12">
                {data.featuredTools.map((tool) => (
                  <Link
                    key={tool.id}
                    href={`/tool/${tool.package.npmPackageName}/${tool.name}`}
                    className="group"
                  >
                    <div className="p-6 border border-border rounded-lg bg-surface hover:border-foreground transition-colors h-full flex flex-col">
                      <div className="flex items-start justify-between gap-2 mb-3">
                        <h3 className="text-lg font-semibold text-foreground group-hover:text-brutalist-accent transition-colors min-w-0 break-words">
                          {tool.package.npmPackageName}
                          <span className="text-xs text-foreground-tertiary ml-2">
                            ({tool.name})
                          </span>
                        </h3>
                        {tool.package.isOfficial && (
                          <Badge variant="default" size="sm" className="flex-shrink-0">
                            Official
                          </Badge>
                        )}
                      </div>

                      <p className="text-sm text-foreground-secondary mb-4 flex-1 line-clamp-3">
                        {tool.description}
                      </p>

                      <div className="flex items-center gap-2 flex-wrap">
                        <Badge variant="outline" size="sm">
                          {tool.package.category}
                        </Badge>
                      </div>

                      <div className="mt-4 pt-4 border-t border-border flex items-center justify-between text-xs text-foreground-tertiary">
                        <div className="flex items-center gap-3">
                          {tool.qualityScore && Number(tool.qualityScore) > 0 ? (
                            <span className="flex items-center gap-1">
                              <span className="text-brutalist-accent">★</span>
                              {Number(tool.qualityScore).toFixed(2)}
                            </span>
                          ) : null}
                          {tool.likeCount > 0 && (
                            <span className="flex items-center gap-1">
                              <Icon icon="heart" className="w-3 h-3 text-error" />
                              {tool.likeCount}
                            </span>
                          )}
                        </div>
                        <span>
                          {(tool.package.npmDownloadsLastMonth ?? 0) > 0
                            ? `${tool.package.npmDownloadsLastMonth?.toLocaleString()} downloads/mo`
                            : 'New'}
                        </span>
                      </div>
                    </div>
                  </Link>
                ))}
              </div>
            ) : (
              <div className="text-center py-12">
                <p className="text-foreground-secondary">
                  No tools available yet. Check back soon!
                </p>
              </div>
            )}

            <div className="flex flex-col sm:flex-row gap-4 justify-center items-center">
              <Link href="/tool/tool-search">
                <Button size="lg" variant="default">
                  Browse All {data.stats.toolCount} Tools
                </Button>
              </Link>
              <Link href="/tool/tool-search">
                <Button size="lg" variant="outline">
                  Search by Category
                </Button>
              </Link>
            </div>
          </Container>
        </section>

        {/* Featured Scenarios Section */}
        {data.featuredScenarios.length > 0 && (
          <section className="py-16 bg-surface border-t border-border">
            <Container size="xl" padding="lg">
              <div className="text-center mb-12">
                <h2 className="text-3xl md:text-4xl font-bold mb-4 text-foreground">
                  Test Scenarios
                </h2>
                <p className="text-lg text-foreground-secondary max-w-2xl mx-auto mb-8">
                  See how tool collections are tested with AI-generated scenarios. Real execution,
                  real results.
                </p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 md:gap-6 mb-12">
                {data.featuredScenarios.map((scenario) => {
                  const qualityPercent = Math.round(scenario.qualityScore * 100);
                  const qualityColor =
                    qualityPercent >= 70
                      ? 'text-success'
                      : qualityPercent >= 40
                        ? 'text-warning'
                        : 'text-foreground-tertiary';

                  return (
                    <Link
                      key={scenario.id}
                      href={
                        scenario.collection
                          ? `/@${scenario.collection.user.username}/collections/${scenario.collection.slug}/scenarios/${scenario.id}`
                          : `/scenarios/${scenario.id}`
                      }
                      className="group"
                    >
                      <div className="p-6 border border-border rounded-lg bg-background hover:border-foreground transition-colors h-full flex flex-col">
                        <div className="flex items-start justify-between gap-2 mb-3">
                          <h3 className="text-lg font-semibold text-foreground group-hover:text-brutalist-accent transition-colors min-w-0 break-words line-clamp-1">
                            {scenario.name ||
                              (scenario.prompt.length > 50
                                ? `${scenario.prompt.slice(0, 50)}...`
                                : scenario.prompt)}
                          </h3>
                          {scenario.lastRunStatus === 'pass' && (
                            <Badge
                              size="sm"
                              className="flex-shrink-0 bg-success/10 text-success border-success/20"
                            >
                              <Icon icon="check" className="w-3 h-3 mr-1" />
                              Pass
                            </Badge>
                          )}
                          {scenario.lastRunStatus === 'fail' && (
                            <Badge
                              size="sm"
                              className="flex-shrink-0 bg-error/10 text-error border-error/20"
                            >
                              <Icon icon="x" className="w-3 h-3 mr-1" />
                              Fail
                            </Badge>
                          )}
                        </div>

                        <p className="text-sm text-foreground-secondary mb-4 flex-1 line-clamp-2">
                          {scenario.prompt}
                        </p>

                        {scenario.collection && (
                          <div className="flex items-center gap-2 mb-4">
                            <Badge variant="outline" size="sm">
                              {scenario.collection.name}
                            </Badge>
                            <span className="text-xs text-foreground-tertiary">
                              by @{scenario.collection.user.username}
                            </span>
                          </div>
                        )}

                        {scenario.tags.length > 0 && (
                          <div className="flex flex-wrap gap-1 mb-4">
                            {scenario.tags.slice(0, 3).map((tag) => (
                              <Badge key={tag} variant="secondary" size="sm" className="text-xs">
                                {tag}
                              </Badge>
                            ))}
                          </div>
                        )}

                        <div className="mt-auto pt-4 border-t border-border flex items-center justify-between text-xs text-foreground-tertiary">
                          <span className={`flex items-center gap-1 ${qualityColor}`}>
                            <Icon icon="star" className="w-3.5 h-3.5" />
                            {qualityPercent}% quality
                          </span>
                          <span>{scenario.totalRuns} runs</span>
                        </div>
                      </div>
                    </Link>
                  );
                })}
              </div>

              <div className="flex justify-center">
                <Link href="/scenarios">
                  <Button size="lg" variant="outline">
                    Browse All Scenarios
                  </Button>
                </Link>
              </div>
            </Container>
          </section>
        )}

        {/* MCP Integration Section */}
        <McpSection toolCount={data.stats.toolCount} />

        {/* Publish Your Tool Section */}
        <section className="py-16 bg-surface">
          <Container size="xl" padding="lg">
            <div className="text-center max-w-3xl mx-auto">
              <h2 className="text-3xl md:text-4xl font-bold mb-4 text-foreground">
                Publish Your AI Tool
              </h2>
              <p className="text-lg text-foreground-secondary mb-8">
                Share your tool with the AI community. Automatic discovery, quality scoring, and
                integration with Vercel AI SDK, LangChain, and more.
              </p>

              {/* Generator Highlight Box */}
              <div className="mb-12 p-6 border-2 border-primary/50 rounded-lg bg-primary/5 text-left">
                <div className="flex flex-col sm:flex-row items-start gap-4">
                  <div className="text-3xl sm:text-4xl" aria-hidden="true">
                    ✨
                  </div>
                  <div className="flex-1">
                    <h3 className="text-xl font-bold mb-2 text-foreground">
                      Start with Our Package Generator
                    </h3>
                    <p className="text-sm text-foreground-secondary mb-4">
                      Create a production-ready TPMJS tool package in seconds with our CLI
                      generator. Includes 2-3 tools, complete setup, and best practices.
                    </p>
                    <div className="flex flex-col sm:flex-row gap-3">
                      <code className="text-sm bg-surface px-4 py-2 rounded text-foreground border border-border">
                        npx @tpmjs/create-basic-tools
                      </code>
                      <a
                        href="https://github.com/tpmjs/tpmjs/tree/main/packages/tools/create-basic-tools#readme"
                        target="_blank"
                        rel="noopener noreferrer"
                      >
                        <Button size="sm" variant="outline">
                          View Docs →
                        </Button>
                      </a>
                    </div>
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-4 md:gap-6 mb-8">
                <div className="p-4">
                  <div className="text-3xl mb-2" aria-hidden="true">
                    🚀
                  </div>
                  <h3 className="font-semibold mb-1 text-foreground">Quick Setup</h3>
                  <p className="text-sm text-foreground-secondary">
                    Add one keyword to package.json and publish to NPM
                  </p>
                </div>
                <div className="p-4">
                  <div className="text-3xl mb-2" aria-hidden="true">
                    ⚡
                  </div>
                  <h3 className="font-semibold mb-1 text-foreground">Auto Discovery</h3>
                  <p className="text-sm text-foreground-secondary">
                    Your tool appears on tpmjs.com within 15 minutes
                  </p>
                </div>
                <div className="p-4">
                  <div className="text-3xl mb-2" aria-hidden="true">
                    📊
                  </div>
                  <h3 className="font-semibold mb-1 text-foreground">Quality Metrics</h3>
                  <p className="text-sm text-foreground-secondary">
                    Automatic scoring based on docs, downloads, and stars
                  </p>
                </div>
              </div>
              <Link href="/publish">
                <Button size="lg" variant="default">
                  Learn How to Publish
                </Button>
              </Link>
            </div>
          </Container>
        </section>
      </main>
    </>
  );
}

// This is your Prisma schema file,
// learn more about it in the docs: https://pris.ly/d/prisma-schema

generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider  = "postgresql"
  url       = env("DATABASE_URL")
  directUrl = env("DATABASE_URL_UNPOOLED") // Direct connection for migrations (bypasses pooler)
}

/// Package table - stores NPM package metadata (package-level)
model Package {
  id String @id @default(cuid())

  // NPM Metadata
  npmPackageName String   @unique @map("npm_package_name") @db.VarChar(214)
  npmVersion     String   @map("npm_version") @db.VarChar(50)
  npmPublishedAt DateTime @map("npm_published_at")
  npmDescription String?  @map("npm_description") @db.Text
  npmRepository  Json?    @map("npm_repository") @db.JsonB
  npmHomepage    String?  @map("npm_homepage") @db.Text
  npmLicense     String?  @map("npm_license") @db.VarChar(50)
  npmKeywords    String[] @default([]) @map("npm_keywords") @db.Text
  npmReadme      String?  @map("npm_readme") @db.Text
  npmAuthor      Json?    @map("npm_author") @db.JsonB
  npmMaintainers Json?    @map("npm_maintainers") @db.JsonB

  // TPMJS Package-Level Metadata
  category       String   @db.VarChar(50)
  env            Json?    @db.JsonB // Environment variables (shared across tools)
  frameworks     String[] @default([]) @db.Text
  tier           String   @db.VarChar(20) // 'minimal' | 'rich'
  discoveryMethod String  @map("discovery_method") @db.VarChar(20) // 'keyword' | 'changes-feed'
  isOfficial     Boolean  @default(false) @map("is_official")

  // Package Metrics
  npmDownloadsLastMonth Int? @default(0) @map("npm_downloads_last_month")
  githubStars           Int? @default(0) @map("github_stars")

  // Timestamps
  createdAt DateTime @default(now()) @map("created_at")
  updatedAt DateTime @updatedAt @map("updated_at")

  // Relations
  tools Tool[]

  @@index([category])
  @@index([isOfficial])
  @@index([npmDownloadsLastMonth])
  @@index([createdAt])
  @@map("packages")
}

/// Tool table - stores individual tools within packages
model Tool {
  id String @id @default(cuid())

  // Package Relation
  packageId String  @map("package_id")
  package   Package @relation(fields: [packageId], references: [id], onDelete: Cascade)

  // Tool Identity
  name String @db.VarChar(100) // e.g., "helloWorldTool", "default"

  // Tool Metadata
  description String @db.Text
  parameters  Json?  @db.JsonB // Legacy/fallback - author-provided parameters array
  returns     Json?  @db.JsonB // @deprecated - will be auto-extracted in future
  aiAgent     Json?  @map("ai_agent") @db.JsonB // @deprecated - will be auto-extracted in future

  // Schema Extraction Fields
  inputSchema                Json?     @map("input_schema") @db.JsonB // Full JSON Schema from executor
  schemaSource               String?   @map("schema_source") @db.VarChar(20) // 'extracted' | 'author' | null
  schemaExtractedAt          DateTime? @map("schema_extracted_at") // Only updated on successful extraction
  schemaExtractionAttemptAt  DateTime? @map("schema_extraction_attempt_at") // Updated on every attempt (for rate limiting)
  schemaExtractionError      String?   @map("schema_extraction_error") @db.Text // Error message from last failed attempt

  // Tool Discovery Fields
  toolDiscoverySource String? @map("tool_discovery_source") @db.VarChar(20) // 'auto' | 'manual' | null

  // Tool Metrics
  qualityScore Decimal? @map("quality_score") @db.Decimal(3, 2) // 0.00 to 1.00
  likeCount    Int      @default(0) @map("like_count")

  // Health Status Fields
  importHealth     HealthStatus? @default(UNKNOWN) @map("import_health")
  executionHealth  HealthStatus? @default(UNKNOWN) @map("execution_health")
  lastHealthCheck  DateTime?     @map("last_health_check")
  healthCheckError String?       @map("health_check_error") @db.Text

  // Timestamps
  createdAt DateTime @default(now()) @map("created_at")
  updatedAt DateTime @updatedAt @map("updated_at")

  // View tracking (denormalized, rolled up daily)
  viewCount      Int      @default(0) @map("view_count")

