'use client';

import { Container } from '@tpmjs/ui/Container/Container';
import { DitherSectionHeader } from '@tpmjs/ui/DitherText/DitherSectionHeader';
import { StatCard } from '@tpmjs/ui/StatCard/StatCard';
import { PublicActivityStream } from './PublicActivityStream';

interface EcosystemStatsProps {
  stats: {
    publishedTools: number;
    activeDevelopers: number;
    totalExecutions: number;
    avgResponseMs: number | null;
    totalDownloads: number;
  };
}

export function EcosystemStats({ stats }: EcosystemStatsProps): React.ReactElement {
  const statistics = [
    {
      value: stats.publishedTools,
      label: 'Published Tools',
      subtext: 'Auto-synced from npm',
      suffix: '',
    },
    {
      value: stats.activeDevelopers,
      label: 'Active Developers',
      subtext: 'Last 7 days',
      suffix: '',
    },
    {
      value: stats.totalExecutions,
      label: 'Total Executions',
      subtext: 'All-time simulations',
      suffix: '',
    },
    {
      value: stats.avgResponseMs ? Math.round(stats.avgResponseMs / 100) / 10 : 0,
      label: 'Avg Response',
      subtext: 'Execution latency',
      suffix: 's',
      decimals: 1,
    },
  ];

  return (
    <section className="py-16 md:py-24 bg-surface relative overflow-hidden">
      {/* Subtle grid background */}
      <div className="absolute inset-0 opacity-[0.02] grid-background" />

      <Container size="xl" padding="lg" className="relative z-10">
        <DitherSectionHeader className="mb-12 text-center">LIVE ECOSYSTEM</DitherSectionHeader>

        {/* Stats Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-12">
          {statistics.map((stat, index) => (
            <div
              key={stat.label}
              className={`opacity-0 animate-brutalist-entrance stagger-${index + 1}`}
            >
              <StatCard
                value={stat.value}
                label={stat.label}
                subtext={stat.subtext}
                suffix={stat.suffix}
                decimals={stat.decimals}
                variant="brutalist"
                size="md"
                showBar={true}
                barProgress={60 + index * 10}
              />
            </div>
          ))}
        </div>

        {/* Activity Stream */}
        <div className="max-w-3xl mx-auto">
          <PublicActivityStream />
        </div>
      </Container>
    </section>
  );
}

'use client';

import { Button } from '@tpmjs/ui/Button/Button';
import { Container } from '@tpmjs/ui/Container/Container';
import { Icon } from '@tpmjs/ui/Icon/Icon';
import Link from 'next/link';
import { useState } from 'react';

interface McpSectionProps {
  toolCount: number;
}

const EXAMPLE_URL = 'https://tpmjs.com/@username/collections/my-tools/mcp';

type Provider = 'claude-code' | 'claude-desktop' | 'cursor' | 'windsurf' | 'any';

interface ProviderInfo {
  id: Provider;
  label: string;
  shortLabel: string;
  icon: string;
  description: string;
}

const providers: ProviderInfo[] = [
  {
    id: 'claude-code',
    label: 'Claude Code',
    shortLabel: 'Claude Code',
    icon: '>_',
    description: 'cli / terminal',
  },
  {
    id: 'claude-desktop',
    label: 'Claude Desktop',
    shortLabel: 'Desktop',
    icon: 'C',
    description: 'desktop app',
  },
  {
    id: 'cursor',
    label: 'Cursor',
    shortLabel: 'Cursor',
    icon: '{;}',
    description: 'ai code editor',
  },
  {
    id: 'windsurf',
    label: 'Windsurf',
    shortLabel: 'Windsurf',
    icon: 'W',
    description: 'agentic ide',
  },
  {
    id: 'any',
    label: 'Any MCP Client',
    shortLabel: 'Other',
    icon: '*',
    description: 'open protocol',
  },
];

function CopyButton({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);

  const copy = async () => {
    await navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <button
      type="button"
      onClick={copy}
      className="absolute top-3 right-3 p-1.5 text-foreground-tertiary hover:text-foreground transition-colors"
      aria-label="Copy to clipboard"
    >
      <Icon icon={copied ? 'check' : 'copy'} size="xs" />
    </button>
  );
}

function CodeBlock({ code, filename }: { code: string; filename?: string }) {
  return (
    <div className="relative">
      {filename && (
        <div className="px-4 py-2 border-b border-border bg-surface font-mono text-xs text-foreground-tertiary">
          {filename}
        </div>
      )}
      <div className="p-4 bg-background font-mono text-sm overflow-x-auto">
        <pre className="text-foreground whitespace-pre">{code}</pre>
      </div>
      <CopyButton text={code} />
    </div>
  );
}

function ProviderConfig({ provider }: { provider: Provider }) {
  switch (provider) {
    case 'claude-code':
      return (
        <div className="space-y-4">
          <div className="border border-border overflow-hidden">
            <div className="px-4 py-2 bg-surface border-b border-border">
              <p className="font-mono text-xs text-foreground-tertiary">
                one command — that&apos;s it
              </p>
            </div>
            <CodeBlock code={`claude mcp add my-tools \\\n  ${EXAMPLE_URL} \\\n  -t http`} />
          </div>
          <div className="flex items-start gap-3 p-3 bg-surface border border-dashed border-border">
            <span className="font-mono text-xs text-primary mt-0.5">tip</span>
            <p className="font-mono text-xs text-foreground-secondary">
              run{' '}
              <code className="px-1 py-0.5 bg-background border border-border text-foreground">
                /mcp
              </code>{' '}
              in Claude Code to verify the server is connected. run{' '}
              <code className="px-1 py-0.5 bg-background border border-border text-foreground">
                claude mcp list
              </code>{' '}
              to see all configured servers.
            </p>
          </div>
        </div>
      );

    case 'claude-desktop':
      return (
        <div className="space-y-4">
          <div className="border border-border overflow-hidden">
            <CodeBlock
              filename="claude_desktop_config.json"
              code={JSON.stringify(
                {
                  mcpServers: {
                    'my-tools': {
                      type: 'http',
                      url: EXAMPLE_URL,
                    },
                  },
                },
                null,
                2
              )}
            />
          </div>
          <div className="flex items-start gap-3 p-3 bg-surface border border-dashed border-border">
            <span className="font-mono text-xs text-primary mt-0.5">path</span>
            <div className="font-mono text-xs text-foreground-secondary space-y-1">
              <p>
                <span className="text-foreground-tertiary">macos:</span> ~/Library/Application
                Support/Claude/claude_desktop_config.json
              </p>
              <p>
                <span className="text-foreground-tertiary">windows:</span>{' '}
                %APPDATA%\Claude\claude_desktop_config.json
              </p>
            </div>
          </div>
        </div>
      );

    case 'cursor':
      return (
        <div className="space-y-4">
          <div className="border border-border overflow-hidden">
            <CodeBlock
              filename=".cursor/mcp.json"
              code={JSON.stringify(
                {
                  mcpServers: {
                    'my-tools': {
                      type: 'http',
                      url: EXAMPLE_URL,
                    },
                  },
                },
                null,
                2
              )}
            />
          </div>
          <div className="flex items-start gap-3 p-3 bg-surface border border-dashed border-border">
            <span className="font-mono text-xs text-primary mt-0.5">alt</span>
            <p className="font-mono text-xs text-foreground-secondary">
              or add via{' '}
              <code className="px-1 py-0.5 bg-background border border-border text-foreground">
                Settings &gt; Features &gt; MCP Servers &gt; + Add Server
              </code>
            </p>
          </div>
        </div>
      );

    case 'windsurf':
      return (
        <div className="space-y-4">
          <div className="border border-border overflow-hidden">
            <CodeBlock
