  1→import { prisma } from '@tpmjs/db';
  2→import { type NextRequest, NextResponse } from 'next/server';
  3→
  4→export const runtime = 'nodejs';
  5→export const dynamic = 'force-dynamic';
  6→export const maxDuration = 60;
  7→
  8→const API_VERSION = '1.0.0';
  9→
 10→interface ApiResponse<T = unknown> {
 11→  success: boolean;
 12→  data?: T;
 13→  error?: {
 14→    code: string;
 15→    message: string;
 16→    details?: Record<string, unknown>;
 17→  };
 18→  meta: {
 19→    version: string;
 20→    timestamp: string;
 21→    requestId?: string;
 22→  };
 23→}
 24→
 25→/**
 26→ * GET /api/public/collections
 27→ * Get public collections sorted by like count
 28→ */
 29→export async function GET(request: NextRequest): Promise<NextResponse<ApiResponse>> {
 30→  const requestId = crypto.randomUUID();
 31→
 32→  try {
 33→    const { searchParams } = new URL(request.url);
 34→    const limit = Math.min(Math.max(Number.parseInt(searchParams.get('limit') || '20', 10), 1), 50);
 35→    const offset = Math.max(Number.parseInt(searchParams.get('offset') || '0', 10), 0);
 36→    const search = searchParams.get('search') || '';
 37→    const sort = searchParams.get('sort') || 'likes'; // 'likes' | 'recent' | 'tools'
 38→
 39→    const where = {
 40→      isPublic: true,
 41→      ...(search && {
 42→        OR: [
 43→          { name: { contains: search, mode: 'insensitive' as const } },
 44→          { description: { contains: search, mode: 'insensitive' as const } },
 45→        ],
 46→      }),
 47→    };
 48→
 49→    const orderBy =
 50→      sort === 'recent'
 51→        ? { createdAt: 'desc' as const }
 52→        : sort === 'tools'
 53→          ? { tools: { _count: 'desc' as const } }
 54→          : { likeCount: 'desc' as const };
 55→
 56→    const collections = await prisma.collection.findMany({
 57→      where,
 58→      include: {
 59→        user: {
 60→          select: {
 61→            id: true,
 62→            name: true,
 63→            image: true,
 64→            username: true,
 65→          },
 66→        },
 67→        _count: {
 68→          select: { tools: true },
 69→        },
 70→      },
 71→      orderBy: [orderBy, { createdAt: 'desc' }],
 72→      take: limit + 1,
 73→      skip: offset,
 74→    });
 75→
 76→    const hasMore = collections.length > limit;
 77→    const data = hasMore ? collections.slice(0, limit) : collections;
 78→
 79→    return NextResponse.json({
 80→      success: true,
 81→      data: data.map((collection) => ({
 82→        id: collection.id,
 83→        slug: collection.slug,
 84→        name: collection.name,
 85→        description: collection.description,
 86→        likeCount: collection.likeCount,
 87→        forkCount: collection.forkCount,
 88→        toolCount: collection._count.tools,
 89→        createdAt: collection.createdAt,
 90→        createdBy: collection.user,
 91→      })),
 92→      pagination: {
 93→        limit,
 94→        offset,
 95→        hasMore,
 96→      },
 97→      meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
 98→    });
 99→  } catch (error) {
100→    console.error('[API Error] GET /api/public/collections:', error);
101→    return NextResponse.json(
102→      {
