import { NextResponse } from 'next/server';

/**
 * Standardized API Response Format
 *
 * All API endpoints should use this helper for consistent response formatting.
 *
 * Success response:
 * {
 *   success: true,
 *   data: T,
 *   meta: { version, timestamp, requestId },
 *   pagination?: { ... }
 * }
 *
 * Error response:
 * {
 *   success: false,
 *   error: { code, message, details? },
 *   meta: { version, timestamp, requestId }
 * }
 */

const API_VERSION = '1.0.0';

export interface ApiError {
  code: string;
  message: string;
  details?: Record<string, unknown>;
}

export interface ApiMeta {
  version: string;
  timestamp: string;
  requestId: string;
}

export interface ApiSuccessResponse<T = unknown> {
  success: true;
  data: T;
  meta: ApiMeta;
  pagination?: Record<string, unknown>;
}

export interface ApiErrorResponse {
  success: false;
  error: ApiError;
  meta: ApiMeta;
}

  @@index([createdAt])
  @@index([endpoint])
  @@index([resourceType, resourceId])
  @@map("api_usage_records")
}

/// ApiUsageSummary - aggregated usage summaries (hourly/daily rollups)
model ApiUsageSummary {
  id                 String   @id @default(cuid())

  // User relationship
  userId             String   @map("user_id")
  user               User     @relation("UserUsageSummaries", fields: [userId], references: [id], onDelete: Cascade)

  // Optional API key (null for user-level summaries)
  apiKeyId           String?  @map("api_key_id")

  // Time period
  periodType         String   @map("period_type") @db.VarChar(20) // "hourly" | "daily" | "monthly"
  periodStart        DateTime @map("period_start")

  // Request counts
  totalRequests      Int      @default(0) @map("total_requests")
  successRequests    Int      @default(0) @map("success_requests")
