  1→import { prisma } from '@tpmjs/db';
  2→import { headers } from 'next/headers';
  3→import { NextResponse } from 'next/server';
  4→import { logActivity } from '~/lib/activity';
  5→import {
  6→  type ApiKeyScope,
  7→  DEFAULT_API_KEY_SCOPES,
  8→  generateApiKey,
  9→  maskApiKey,
 10→} from '~/lib/api-keys';
 11→import { auth } from '~/lib/auth';
 12→
 13→export const runtime = 'nodejs';
 14→export const dynamic = 'force-dynamic';
 15→
 16→/**
 17→ * GET /api/user/tpmjs-api-keys
 18→ *
 19→ * List all API keys for the authenticated user.
 20→ * Requires session auth (not API key auth) for security.
 21→ */
 22→export async function GET() {
 23→  try {
 24→    const session = await auth.api.getSession({ headers: await headers() });
 25→    if (!session?.user?.id) {
 26→      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
 27→    }
 28→
 29→    const apiKeys = await prisma.tpmjsApiKey.findMany({
 30→      where: { userId: session.user.id },
 31→      select: {
 32→        id: true,
 33→        name: true,
 34→        keyPrefix: true,
 35→        scopes: true,
 36→        rateLimit: true,
 37→        isActive: true,
 38→        lastUsedAt: true,
 39→        expiresAt: true,
 40→        createdAt: true,
 41→      },
 42→      orderBy: { createdAt: 'desc' },
 43→    });
 44→
 45→    return NextResponse.json({
 46→      success: true,
 47→      apiKeys: apiKeys.map((key) => ({
 48→        ...key,
 49→        maskedKey: maskApiKey(key.keyPrefix),
 50→      })),
 51→    });
 52→  } catch (error) {
 53→    console.error('[API Keys] Error listing keys:', error);
 54→    return NextResponse.json({ error: 'Failed to list API keys' }, { status: 500 });
 55→  }
 56→}
 57→
 58→/**
 59→ * POST /api/user/tpmjs-api-keys
 60→ *
 61→ * Create a new API key for the authenticated user.
 62→ * Returns the raw key ONLY ONCE - it cannot be retrieved again.
 63→ *
 64→ * Request body:
 65→ * {
 66→ *   name: string;          // Required: User-friendly name
 67→ *   scopes?: string[];     // Optional: Permissions (defaults to all)
 68→ *   expiresAt?: string;    // Optional: ISO date string for expiration
 69→ * }
 70→ */
 71→export async function POST(request: Request) {
 72→  try {
 73→    const session = await auth.api.getSession({ headers: await headers() });
 74→    if (!session?.user?.id) {
 75→      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
 76→    }
 77→
 78→    const body = await request.json();
 79→    const { name, scopes, expiresAt } = body;
 80→
 81→    // Validate name
 82→    if (!name || typeof name !== 'string' || name.trim().length === 0) {
 83→      return NextResponse.json({ error: 'Name is required' }, { status: 400 });
 84→    }
 85→
 86→    if (name.length > 100) {
 87→      return NextResponse.json({ error: 'Name must be 100 characters or less' }, { status: 400 });
 88→    }
 89→
 90→    // Validate scopes
 91→    const validScopes: ApiKeyScope[] = scopes?.length > 0 ? scopes : DEFAULT_API_KEY_SCOPES;
 92→
 93→    // Validate expiration
 94→    let expiresAtDate: Date | undefined;
 95→    if (expiresAt) {
 96→      expiresAtDate = new Date(expiresAt);
 97→      if (Number.isNaN(expiresAtDate.getTime())) {
 98→        return NextResponse.json({ error: 'Invalid expiration date' }, { status: 400 });
 99→      }
100→      if (expiresAtDate <= new Date()) {
101→        return NextResponse.json(
102→          { error: 'Expiration date must be in the future' },
103→          { status: 400 }
104→        );
105→      }
106→    }
107→
108→    // Check key limit (max 10 keys per user)
109→    const existingKeyCount = await prisma.tpmjsApiKey.count({
110→      where: { userId: session.user.id },
111→    });
112→
113→    if (existingKeyCount >= 10) {
114→      return NextResponse.json(
115→        { error: 'Maximum of 10 API keys allowed. Please delete an existing key first.' },
116→        { status: 400 }
117→      );
118→    }
119→
120→    // Generate the key
121→    const { rawKey, keyHash, keyPrefix } = generateApiKey();
122→
123→    // Create the key in database
124→    const apiKey = await prisma.tpmjsApiKey.create({
125→      data: {
126→        userId: session.user.id,
127→        name: name.trim(),
128→        keyHash,
129→        keyPrefix,
130→        scopes: validScopes,
131→        expiresAt: expiresAtDate,
132→      },
133→    });
134→
135→    // Log activity (fire-and-forget)
136→    logActivity({
137→      userId: session.user.id,
138→      type: 'API_KEY_CREATED',
139→      targetName: apiKey.name,
140→      targetType: 'api_key',
141→    });
142→
143→    // Return the raw key - ONLY TIME it's shown!
144→    return NextResponse.json({
145→      success: true,
146→      apiKey: {
147→        id: apiKey.id,
148→        name: apiKey.name,
149→        key: rawKey, // IMPORTANT: Only shown once!
150→        keyPrefix: apiKey.keyPrefix,
151→        scopes: apiKey.scopes,
152→        expiresAt: apiKey.expiresAt,
153→        createdAt: apiKey.createdAt,
154→      },
155→      message: 'API key created. Copy the key now - it will not be shown again!',
156→    });
157→  } catch (error) {
158→    console.error('[API Keys] Error creating key:', error);
159→    return NextResponse.json({ error: 'Failed to create API key' }, { status: 500 });
160→  }
161→}
162→

