  1→import { prisma } from '@tpmjs/db';
  2→import { COLLECTION_LIMITS, CreateCollectionSchema } from '@tpmjs/types/collection';
  3→import { type NextRequest, NextResponse } from 'next/server';
  4→import { logActivity } from '~/lib/activity';
  5→import { authenticateRequest } from '~/lib/api-keys/middleware';
  6→
  7→export const runtime = 'nodejs';
  8→export const dynamic = 'force-dynamic';
  9→export const maxDuration = 60;
 10→
 11→const API_VERSION = '1.0.0';
 12→
 13→/**
 14→ * Generate a URL-friendly slug from a name
 15→ */
 16→function slugify(name: string): string {
 17→  return name
 18→    .toLowerCase()
 19→    .trim()
 20→    .replace(/[^\w\s-]/g, '') // Remove special chars
 21→    .replace(/\s+/g, '-') // Replace spaces with hyphens
 22→    .replace(/-+/g, '-') // Remove consecutive hyphens
 23→    .replace(/^-+|-+$/g, '') // Trim hyphens
 24→    .slice(0, 50);
 25→}
 26→
 27→/**
 28→ * Generate a unique slug for a collection within a user's scope
 29→ */
 30→async function generateUniqueSlug(userId: string, baseName: string): Promise<string> {
 31→  let slug = slugify(baseName);
 32→  if (!slug) slug = 'collection';
 33→
 34→  // Check if slug exists for this user
 35→  const existing = await prisma.collection.findFirst({
 36→    where: { userId, slug },
 37→    select: { id: true },
 38→  });
 39→
 40→  if (!existing) return slug;
 41→
 42→  // Append numbers until unique
 43→  let counter = 1;
 44→  while (counter < 1000) {
 45→    const candidate = `${slug.slice(0, 46)}-${counter}`;
 46→    const exists = await prisma.collection.findFirst({
 47→      where: { userId, slug: candidate },
 48→      select: { id: true },
 49→    });
 50→    if (!exists) return candidate;
 51→    counter++;
 52→  }
 53→
 54→  // Fallback: use random suffix
 55→  return `${slug.slice(0, 42)}-${Date.now().toString(36)}`;
 56→}
 57→
 58→/**
 59→ * Standard API response structure
 60→ */
 61→interface ApiResponse<T = unknown> {
 62→  success: boolean;
 63→  data?: T;
 64→  error?: {
 65→    code: string;
 66→    message: string;
 67→    details?: Record<string, unknown>;
 68→  };
 69→  meta: {
 70→    version: string;
 71→    timestamp: string;
 72→    requestId?: string;
 73→  };
 74→  pagination?: {
 75→    limit: number;
 76→    offset: number;
 77→    count: number;
 78→    hasMore: boolean;
 79→  };
 80→}
 81→
 82→/**
 83→ * GET /api/collections
 84→ * List all collections for the authenticated user
 85→ */
 86→export async function GET(request: NextRequest): Promise<NextResponse<ApiResponse>> {
 87→  const requestId = crypto.randomUUID();
 88→
 89→  try {
 90→    // Check authentication
 91→    const authResult = await authenticateRequest();
 92→
 93→    if (!authResult.authenticated || !authResult.userId) {
 94→      return NextResponse.json(
 95→        {
 96→          success: false,
 97→          error: { code: 'UNAUTHORIZED', message: 'Authentication required' },
 98→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
 99→        },
100→        { status: 401 }
101→      );
102→    }
103→
104→    // Parse pagination and search params
105→    const searchParams = request.nextUrl.searchParams;
106→    const limit = Math.min(Math.max(Number.parseInt(searchParams.get('limit') || '20', 10), 1), 50);
107→    const offset = Math.max(Number.parseInt(searchParams.get('offset') || '0', 10), 0);
108→    const search = searchParams.get('search')?.trim();
109→
110→    // Fetch collections with tool count
111→    const collections = await prisma.collection.findMany({
112→      where: {
113→        userId: authResult.userId,
114→        ...(search && {
115→          OR: [
116→            { name: { contains: search, mode: 'insensitive' } },
117→            { description: { contains: search, mode: 'insensitive' } },
118→          ],
119→        }),
120→      },
121→      include: {
122→        _count: { select: { tools: true } },
123→      },
124→      orderBy: { createdAt: 'desc' },
125→      take: limit + 1,
126→      skip: offset,
127→    });
128→
129→    const hasMore = collections.length > limit;
130→    const data = hasMore ? collections.slice(0, limit) : collections;
131→
132→    return NextResponse.json({
133→      success: true,
134→      data: data.map((c) => ({
135→        id: c.id,
136→        name: c.name,
137→        slug: c.slug,
138→        description: c.description,
139→        isPublic: c.isPublic,
140→        toolCount: c._count.tools,
141→        createdAt: c.createdAt,
142→        updatedAt: c.updatedAt,
143→      })),
144→      meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
145→      pagination: { limit, offset, count: data.length, hasMore },
146→    });
147→  } catch (error) {
148→    console.error('[API Error] GET /api/collections:', error);
149→    return NextResponse.json(
150→      {
151→        success: false,
152→        error: { code: 'INTERNAL_ERROR', message: 'Failed to fetch collections' },
153→        meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
154→      },
155→      { status: 500 }
156→    );
157→  }
158→}
159→
160→/**
161→ * POST /api/collections
162→ * Create a new collection
163→ */
164→export async function POST(request: NextRequest): Promise<NextResponse<ApiResponse>> {
165→  const requestId = crypto.randomUUID();
166→
167→  try {
168→    // Check authentication
169→    const authResult = await authenticateRequest();
170→
171→    if (!authResult.authenticated || !authResult.userId) {
172→      return NextResponse.json(
173→        {
174→          success: false,
175→          error: { code: 'UNAUTHORIZED', message: 'Authentication required' },
176→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
177→        },
178→        { status: 401 }
179→      );
180→    }
181→    const userId = authResult.userId;
182→
183→    // Parse and validate request body
184→    const body = await request.json();
185→    const parseResult = CreateCollectionSchema.safeParse(body);
186→
187→    if (!parseResult.success) {
188→      return NextResponse.json(
189→        {
190→          success: false,
191→          error: {
192→            code: 'VALIDATION_ERROR',
193→            message: 'Invalid request body',
194→            details: { errors: parseResult.error.flatten().fieldErrors },
195→          },
196→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
197→        },
198→        { status: 400 }
199→      );
200→    }
201→
202→    const { name, description, isPublic } = parseResult.data;
203→
204→    // Check collection limit
205→    const existingCount = await prisma.collection.count({
206→      where: { userId },
207→    });
208→
209→    if (existingCount >= COLLECTION_LIMITS.MAX_COLLECTIONS_PER_USER) {
210→      return NextResponse.json(
211→        {
212→          success: false,
213→          error: {
214→            code: 'LIMIT_EXCEEDED',
215→            message: `Maximum ${COLLECTION_LIMITS.MAX_COLLECTIONS_PER_USER} collections allowed`,
216→          },
217→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
218→        },
219→        { status: 400 }
220→      );
221→    }
222→
223→    // Check for duplicate name (case-insensitive)
224→    const existingCollection = await prisma.collection.findFirst({
225→      where: {
226→        userId,
227→        name: { equals: name, mode: 'insensitive' },
228→      },
229→    });
230→
231→    if (existingCollection) {
232→      return NextResponse.json(
233→        {
234→          success: false,
235→          error: {
236→            code: 'DUPLICATE_NAME',
237→            message: 'A collection with this name already exists',
238→          },
239→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
240→        },
241→        { status: 409 }
242→      );
243→    }
244→
245→    // Generate unique slug for the collection
246→    const slug = await generateUniqueSlug(userId, name);
247→
248→    // Create collection with auto-like (user likes their own collection)
249→    const collection = await prisma.$transaction(async (tx) => {
250→      const newCollection = await tx.collection.create({
251→        data: {
252→          userId,
253→          name,
254→          slug,
255→          description: description || null,
256→          isPublic,
257→          likeCount: 1, // Start with 1 like (from owner)
258→        },
259→      });
260→
261→      // Auto-like the collection
262→      await tx.collectionLike.create({
263→        data: {
264→          userId,
265→          collectionId: newCollection.id,
266→        },
267→      });
268→
269→      return newCollection;
270→    });
271→
272→    // Log activity (fire-and-forget)
273→    logActivity({
274→      userId,
275→      type: 'COLLECTION_CREATED',
276→      targetName: collection.name,
277→      targetType: 'collection',
278→      collectionId: collection.id,
279→    });
280→
281→    return NextResponse.json(
282→      {
283→        success: true,
284→        data: {
285→          id: collection.id,
286→          name: collection.name,
287→          slug: collection.slug,
288→          description: collection.description,
289→          isPublic: collection.isPublic,
290→          toolCount: 0,
291→          createdAt: collection.createdAt,
292→          updatedAt: collection.updatedAt,
293→        },
294→        meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
295→      },
296→      { status: 201 }
297→    );
298→  } catch (error) {
299→    console.error('[API Error] POST /api/collections:', error);
300→    return NextResponse.json(
301→      {
302→        success: false,
303→        error: { code: 'INTERNAL_ERROR', message: 'Failed to create collection' },
304→        meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
305→      },
306→      { status: 500 }
307→    );
308→  }
309→}
310→

