import { prisma } from '@tpmjs/db';
import { NextResponse } from 'next/server';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 60;

interface RouteContext {
  params: Promise<{ token: string }>;
}

interface ConfigMapping {
  collectionId: string;
  collectionSlug: string;
  collectionName: string;
  editor: string;
}

interface SetupConfig {
  mappings: ConfigMapping[];
  apiKeyHash?: string;
}

/**
 * GET /api/setup/redeem/[token]
 *
 * Called by install.sh to redeem a setup token and get the configuration payload.
 * One-time use - marks the token as redeemed after successful retrieval.
 */
export async function GET(_request: Request, context: RouteContext) {
  try {
    const { token } = await context.params;

    if (!token || token.length !== 64) {
      return NextResponse.json(
        { success: false, error: 'Invalid token format' },
        { status: 400 }
      );
    }

    // Look up the token
    const setupToken = await prisma.setupToken.findUnique({
      where: { token },
      include: {
        user: {
          select: {
            id: true,
            username: true,
          },
        },
      },
    });

    if (!setupToken) {
      return NextResponse.json(
        { success: false, error: 'Token not found' },
        { status: 404 }
      );
    }

    // Check if already redeemed
    if (setupToken.redeemed) {
      return NextResponse.json(
        { success: false, error: 'Token has already been redeemed' },
        { status: 410 }
      );
    }

    // Check if expired
    if (setupToken.expiresAt < new Date()) {
      return NextResponse.json(
        { success: false, error: 'Token has expired' },
        { status: 410 }
      );
    }

    // Mark as redeemed
    await prisma.setupToken.update({
      where: { id: setupToken.id },
      data: {
        redeemed: true,
        redeemedAt: new Date(),
      },
    });

    const config = setupToken.config as SetupConfig;
    const username = setupToken.user.username || setupToken.user.id;

    // Look up the raw API key prefix if one was created during token creation
    // The actual raw key was returned during create-token; we need to find it for the response
    let apiKey: string | undefined;
    if (config.apiKeyHash) {
      // We stored the keyHash in config - look up the key to get the prefix
      // Note: we can't recover the raw key, but the raw key was stored in the config
      // during creation. We need to find the matching TpmjsApiKey to confirm it exists.
      const tpmjsKey = await prisma.tpmjsApiKey.findFirst({
        where: {
          keyHash: config.apiKeyHash,
          userId: setupToken.userId,
          isActive: true,
        },
        select: { keyPrefix: true },
      });

      if (tpmjsKey) {
        // The API key exists and is active - the raw key was already returned
        // during create-token. The install script should have received it there.
        apiKey = undefined; // Raw key is not recoverable from the hash
      }
    }

    // Build the response payload
    const mappings = config.mappings.map((m) => ({
      collectionSlug: m.collectionSlug,
      collectionName: m.collectionName,
      editor: m.editor,
      mcpUrl: `https://tpmjs.com/@${username}/collections/${m.collectionSlug}/mcp`,
    }));

    return NextResponse.json({
      success: true,
      username,
      mappings,
      // apiKey is not included here since we can't recover the raw key from the hash.
      // The raw key was returned from create-token and should be passed via the token config.
    });
  } catch (error) {
    console.error('[Setup] Error redeeming token:', error);
    return NextResponse.json(
      { success: false, error: 'Failed to redeem token' },
      { status: 500 }
    );
  }
}

