  1→import { randomBytes } from 'node:crypto';
  2→import { prisma } from '@tpmjs/db';
  3→import { headers } from 'next/headers';
  4→import { NextResponse } from 'next/server';
  5→import { DEFAULT_API_KEY_SCOPES, generateApiKey } from '~/lib/api-keys';
  6→import { auth } from '~/lib/auth';
  7→
  8→export const runtime = 'nodejs';
  9→export const dynamic = 'force-dynamic';
 10→export const maxDuration = 60;
 11→
 12→const VALID_EDITORS = ['claude-code', 'cursor', 'windsurf', 'claude-desktop'] as const;
 13→type Editor = (typeof VALID_EDITORS)[number];
 14→
 15→interface MappingInput {
 16→  collectionId: string;
 17→  collectionSlug: string;
 18→  collectionName: string;
 19→  editor: Editor;
 20→}
 21→
 22→interface CreateTokenBody {
 23→  mappings: MappingInput[];
 24→  createApiKey?: boolean;
 25→}
 26→
 27→/**
 28→ * POST /api/setup/create-token
 29→ *
 30→ * Creates a one-time setup token for the install.sh flow.
 31→ * Called from the web UI (authenticated via session).
 32→ */
 33→export async function POST(request: Request) {
 34→  try {
 35→    const session = await auth.api.getSession({ headers: await headers() });
 36→    if (!session?.user?.id) {
 37→      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
 38→    }
 39→
 40→    const body: CreateTokenBody = await request.json();
 41→    const { mappings, createApiKey } = body;
 42→
 43→    // Validate mappings
 44→    if (!Array.isArray(mappings) || mappings.length === 0) {
 45→      return NextResponse.json(
 46→        { error: 'At least one mapping is required' },
 47→        { status: 400 }
 48→      );
 49→    }
 50→
 51→    if (mappings.length > 50) {
 52→      return NextResponse.json(
 53→        { error: 'Maximum 50 mappings allowed' },
 54→        { status: 400 }
 55→      );
 56→    }
 57→
 58→    for (const mapping of mappings) {
 59→      if (!mapping.collectionId || !mapping.collectionSlug || !mapping.collectionName) {
 60→        return NextResponse.json(
 61→          { error: 'Each mapping must include collectionId, collectionSlug, and collectionName' },
 62→          { status: 400 }
 63→        );
 64→      }
 65→      if (!VALID_EDITORS.includes(mapping.editor as Editor)) {
 66→        return NextResponse.json(
 67→          {
 68→            error: `Invalid editor "${mapping.editor}". Must be one of: ${VALID_EDITORS.join(', ')}`,
 69→          },
 70→          { status: 400 }
 71→        );
 72→      }
 73→    }
 74→
 75→    // Validate all collections belong to the user
 76→    const collectionIds = mappings.map((m) => m.collectionId);
 77→    const collections = await prisma.collection.findMany({
 78→      where: {
 79→        id: { in: collectionIds },
 80→        userId: session.user.id,
 81→      },
 82→      select: { id: true },
 83→    });
 84→
 85→    const ownedIds = new Set(collections.map((c) => c.id));
 86→    const invalidIds = collectionIds.filter((id) => !ownedIds.has(id));
 87→    if (invalidIds.length > 0) {
 88→      return NextResponse.json(
 89→        { error: `Collections not found or not owned by you: ${invalidIds.join(', ')}` },
 90→        { status: 403 }
 91→      );
 92→    }
 93→
 94→    // Determine whether to create an API key
 95→    let rawApiKey: string | undefined;
 96→    let apiKeyHash: string | undefined;
 97→
 98→    const shouldCreateKey =
 99→      createApiKey ||
100→      (await prisma.tpmjsApiKey.count({
101→        where: { userId: session.user.id, isActive: true },
102→      })) === 0;
103→
104→    if (shouldCreateKey) {
105→      const { rawKey, keyHash, keyPrefix } = generateApiKey();
106→      rawApiKey = rawKey;
107→      apiKeyHash = keyHash;
108→
109→      await prisma.tpmjsApiKey.create({
110→        data: {
111→          userId: session.user.id,
112→          name: 'Setup (auto-created)',
113→          keyHash,
114→          keyPrefix,
115→          scopes: DEFAULT_API_KEY_SCOPES,
116→        },
117→      });
118→    }
119→
120→    // Generate a random 32-byte hex token
121→    const token = randomBytes(32).toString('hex');
122→
123→    // Create the SetupToken with 1 hour expiry
124→    const expiresAt = new Date(Date.now() + 60 * 60 * 1000);
125→
126→    await prisma.setupToken.create({
127→      data: {
128→        userId: session.user.id,
129→        token,
130→        config: {
131→          mappings: mappings.map((m) => ({
132→            collectionId: m.collectionId,
133→            collectionSlug: m.collectionSlug,
134→            collectionName: m.collectionName,
