  1→import { prisma } from '@tpmjs/db';
  2→import { NextResponse } from 'next/server';
  3→
  4→export const runtime = 'nodejs';
  5→export const dynamic = 'force-dynamic';
  6→export const maxDuration = 60;
  7→
  8→interface RouteContext {
  9→  params: Promise<{ token: string }>;
 10→}
 11→
 12→interface ConfigMapping {
 13→  collectionId: string;
 14→  collectionSlug: string;
 15→  collectionName: string;
 16→  editor: string;
 17→}
 18→
 19→interface SetupConfig {
 20→  mappings: ConfigMapping[];
 21→  apiKey?: string;
 22→}
 23→
 24→/**
 25→ * GET /api/setup/redeem/[token]
 26→ *
 27→ * Called by install.sh to redeem a setup token and get the configuration payload.
 28→ * One-time use - marks the token as redeemed after successful retrieval.
 29→ */
 30→export async function GET(_request: Request, context: RouteContext) {
 31→  try {
 32→    const { token } = await context.params;
 33→
 34→    if (!token || token.length !== 64) {
 35→      return NextResponse.json(
 36→        { success: false, error: 'Invalid token format' },
 37→        { status: 400 }
 38→      );
 39→    }
 40→
 41→    // Look up the token
 42→    const setupToken = await prisma.setupToken.findUnique({
 43→      where: { token },
 44→      include: {
 45→        user: {
 46→          select: {
 47→            id: true,
 48→            username: true,
 49→          },
 50→        },
 51→      },
 52→    });
 53→
 54→    if (!setupToken) {
 55→      return NextResponse.json(
 56→        { success: false, error: 'Token not found' },
 57→        { status: 404 }
 58→      );
 59→    }
 60→
 61→    // Check if already redeemed
 62→    if (setupToken.redeemed) {
 63→      return NextResponse.json(
 64→        { success: false, error: 'Token has already been redeemed' },
 65→        { status: 410 }
 66→      );
 67→    }
 68→
 69→    // Check if expired
 70→    if (setupToken.expiresAt < new Date()) {
 71→      return NextResponse.json(
 72→        { success: false, error: 'Token has expired' },
 73→        { status: 410 }
 74→      );
 75→    }
 76→
 77→    // Mark as redeemed
 78→    await prisma.setupToken.update({
 79→      where: { id: setupToken.id },
 80→      data: {
 81→        redeemed: true,
 82→        redeemedAt: new Date(),
 83→      },
 84→    });
 85→
 86→    const config = setupToken.config as SetupConfig;
 87→    const username = setupToken.user.username || setupToken.user.id;
 88→
 89→    // Build the response payload
 90→    const mappings = config.mappings.map((m) => ({
 91→      collectionSlug: m.collectionSlug,
 92→      collectionName: m.collectionName,
 93→      editor: m.editor,
 94→      mcpUrl: `https://tpmjs.com/@${username}/collections/${m.collectionSlug}/mcp`,
 95→    }));
 96→
 97→    return NextResponse.json({
 98→      success: true,
 99→      username,
100→      mappings,
101→      ...(config.apiKey && { apiKey: config.apiKey }),
102→    });
103→  } catch (error) {
104→    console.error('[Setup] Error redeeming token:', error);
105→    return NextResponse.json(
106→      { success: false, error: 'Failed to redeem token' },
107→      { status: 500 }
108→    );
109→  }
110→}
