 47→echo -e "  MCP Server Setup\${NC}"
 48→echo ""
 49→
 50→# ---- Pre-flight checks ---------------------------------------------------
 51→
 52→# Check for curl
 53→if ! command -v curl &>/dev/null; then
 54→  error "curl is required but not installed."
 55→  exit 1
 56→fi
 57→
 58→# Check for node (needed for JSON config merging)
 59→if ! command -v node &>/dev/null; then
 60→  error "Node.js is required but not installed."
 61→  echo "  Install it from https://nodejs.org or via your package manager."
 62→  exit 1
 63→fi
 64→
 65→# ---- Parse arguments ------------------------------------------------------
 66→
 67→TOKEN=""
 68→for arg in "$@"; do
 69→  case "$arg" in
 70→    --token=*)
 71→      TOKEN="\${arg#--token=}"
 72→      ;;
 73→  esac
 74→done
 75→
 76→if [ -z "$TOKEN" ]; then
 77→  echo ""
 78→  warn "No setup token provided."
 79→  echo ""
 80→  echo "  To get started:"
 81→  echo "    1. Visit \${BOLD}https://tpmjs.com/setup\${NC}"
 82→  echo "    2. Select your collections and editors"
 83→  echo "    3. Copy the install command with your token"
 84→  echo ""
 85→  echo "  Usage:"
 86→  echo "    curl -fsSL https://tpmjs.com/install.sh | bash -s -- --token=YOUR_TOKEN"
 87→  echo ""
 88→  exit 1
 89→fi
 90→
 91→# ---- Redeem the token -----------------------------------------------------
 92→
 93→info "Redeeming setup token..."
 94→
 95→RESPONSE=$(curl -fsSL "https://tpmjs.com/api/setup/redeem/$TOKEN" 2>&1) || {
 96→  error "Failed to redeem token. It may be expired or already used."
 97→  echo "  Visit \${BOLD}https://tpmjs.com/setup\${NC} to generate a new one."
 98→  exit 1
 99→}
100→
101→# Parse JSON using node
102→PARSED=$(node -e "
103→  try {
104→    const data = JSON.parse(process.argv[1]);
105→    if (!data.success) {
106→      console.error('Error: ' + (data.error || 'Unknown error'));
107→      process.exit(1);
108→    }
109→    // Output as tab-separated values for bash consumption
110→    console.log(JSON.stringify(data));
111→  } catch (e) {
112→    console.error('Failed to parse response: ' + e.message);
113→    process.exit(1);
114→  }
115→" "$RESPONSE") || {
116→  error "Failed to parse server response."
117→  exit 1
118→}
119→
120→# Extract fields
121→USERNAME=$(node -e "console.log(JSON.parse(process.argv[1]).username)" "$PARSED")
122→API_KEY=$(node -e "const d=JSON.parse(process.argv[1]); console.log(d.apiKey||'')" "$PARSED")
123→MAPPING_COUNT=$(node -e "console.log(JSON.parse(process.argv[1]).mappings.length)" "$PARSED")
124→
125→success "Authenticated as \${BOLD}$USERNAME\${NC}"
126→
127→if [ -n "$API_KEY" ]; then
128→  info "API key created: \${API_KEY:0:20}..."
129→fi
130→
131→echo ""
132→
133→# ---- Configure editors ----------------------------------------------------
134→
135→CONFIGURED=0
136→FAILED=0
137→
138→for i in $(seq 0 $((MAPPING_COUNT - 1))); do
139→  SLUG=$(node -e "console.log(JSON.parse(process.argv[1]).mappings[$i].collectionSlug)" "$PARSED")
140→  NAME=$(node -e "console.log(JSON.parse(process.argv[1]).mappings[$i].collectionName)" "$PARSED")
141→  EDITOR=$(node -e "console.log(JSON.parse(process.argv[1]).mappings[$i].editor)" "$PARSED")
142→  MCP_URL=$(node -e "console.log(JSON.parse(process.argv[1]).mappings[$i].mcpUrl)" "$PARSED")
143→  SERVER_NAME="tpmjs-$SLUG"
144→
145→  info "Configuring \${BOLD}$NAME\${NC} for \${BOLD}$EDITOR\${NC}..."
146→
147→  case "$EDITOR" in
148→    claude-code)
149→      # Use the claude CLI to add the MCP server
150→      if ! command -v claude &>/dev/null; then
151→        warn "claude CLI not found. Skipping $NAME for Claude Code."
152→        warn "  Install it: npm install -g @anthropic-ai/claude-code"
153→        FAILED=$((FAILED + 1))
154→        continue
155→      fi
156→
157→      MCP_JSON=$(node -e "
158→        const config = {
159→          type: 'http',
160→          url: process.argv[1]
161→        };
162→        if (process.argv[2]) {
163→          config.headers = { Authorization: 'Bearer ' + process.argv[2] };
164→        }
165→        console.log(JSON.stringify(config));
166→      " "$MCP_URL" "$API_KEY")
167→
168→      if claude mcp add-json "$SERVER_NAME" "$MCP_JSON" 2>/dev/null; then
169→        success "$NAME configured for Claude Code"
170→        CONFIGURED=$((CONFIGURED + 1))
171→      else
172→        warn "Failed to configure $NAME for Claude Code"
173→        FAILED=$((FAILED + 1))
174→      fi
175→      ;;
176→
177→    cursor)
178→      CONFIG_PATH="$HOME/.cursor/mcp.json"
179→      node -e "
180→        const fs = require('fs');
181→        const path = require('path');
182→        const configPath = process.argv[1];
183→        const serverName = process.argv[2];
184→        const mcpUrl = process.argv[3];
185→        const apiKey = process.argv[4];
186→        let config = {};
187→        try { config = JSON.parse(fs.readFileSync(configPath, 'utf8')); } catch {}
188→        if (!config.mcpServers) config.mcpServers = {};
189→        const server = { type: 'http', url: mcpUrl };
190→        if (apiKey) server.headers = { Authorization: 'Bearer ' + apiKey };
191→        config.mcpServers[serverName] = server;
192→        fs.mkdirSync(path.dirname(configPath), { recursive: true });
193→        fs.writeFileSync(configPath, JSON.stringify(config, null, 2));
194→      " "$CONFIG_PATH" "$SERVER_NAME" "$MCP_URL" "$API_KEY" && {
195→        success "$NAME configured for Cursor (\${CONFIG_PATH})"
196→        CONFIGURED=$((CONFIGURED + 1))
197→      } || {
198→        warn "Failed to configure $NAME for Cursor"
199→        FAILED=$((FAILED + 1))
200→      }
201→      ;;
202→
203→    windsurf)
204→      CONFIG_PATH="$HOME/.codeium/windsurf/mcp_config.json"
205→      node -e "
206→        const fs = require('fs');
207→        const path = require('path');
208→        const configPath = process.argv[1];
209→        const serverName = process.argv[2];
210→        const mcpUrl = process.argv[3];
211→        const apiKey = process.argv[4];
212→        let config = {};
213→        try { config = JSON.parse(fs.readFileSync(configPath, 'utf8')); } catch {}
214→        if (!config.mcpServers) config.mcpServers = {};
215→        const server = { type: 'http', url: mcpUrl };
216→        if (apiKey) server.headers = { Authorization: 'Bearer ' + apiKey };
217→        config.mcpServers[serverName] = server;
218→        fs.mkdirSync(path.dirname(configPath), { recursive: true });
219→        fs.writeFileSync(configPath, JSON.stringify(config, null, 2));
220→      " "$CONFIG_PATH" "$SERVER_NAME" "$MCP_URL" "$API_KEY" && {
221→        success "$NAME configured for Windsurf (\${CONFIG_PATH})"
222→        CONFIGURED=$((CONFIGURED + 1))
223→      } || {
224→        warn "Failed to configure $NAME for Windsurf"
225→        FAILED=$((FAILED + 1))
226→      }
227→      ;;
228→
229→    claude-desktop)
230→      # Detect OS for config path
231→      if [ "$(uname)" = "Darwin" ]; then
232→        CONFIG_PATH="$HOME/Library/Application Support/Claude/claude_desktop_config.json"
233→      elif [ -n "\${APPDATA:-}" ]; then
234→        CONFIG_PATH="$APPDATA/Claude/claude_desktop_config.json"
235→      else
236→        # Linux fallback
237→        CONFIG_PATH="$HOME/.config/Claude/claude_desktop_config.json"
238→      fi
239→
240→      node -e "
241→        const fs = require('fs');
242→        const path = require('path');
243→        const configPath = process.argv[1];
244→        const serverName = process.argv[2];
245→        const mcpUrl = process.argv[3];
246→        const apiKey = process.argv[4];
247→        let config = {};
248→        try { config = JSON.parse(fs.readFileSync(configPath, 'utf8')); } catch {}
249→        if (!config.mcpServers) config.mcpServers = {};
250→        const server = { type: 'http', url: mcpUrl };
251→        if (apiKey) server.headers = { Authorization: 'Bearer ' + apiKey };
252→        config.mcpServers[serverName] = server;
253→        fs.mkdirSync(path.dirname(configPath), { recursive: true });
254→        fs.writeFileSync(configPath, JSON.stringify(config, null, 2));
255→      " "$CONFIG_PATH" "$SERVER_NAME" "$MCP_URL" "$API_KEY" && {
256→        success "$NAME configured for Claude Desktop (\${CONFIG_PATH})"
257→        CONFIGURED=$((CONFIGURED + 1))
258→      } || {
259→        warn "Failed to configure $NAME for Claude Desktop"
260→        FAILED=$((FAILED + 1))
261→      }
262→      ;;
263→
264→    *)
265→      warn "Unknown editor: $EDITOR. Skipping $NAME."
266→      FAILED=$((FAILED + 1))
267→      ;;
268→  esac
269→done
270→
271→# ---- Summary --------------------------------------------------------------
272→
273→echo ""
274→echo -e "\${BOLD}── Summary ─────────────────────────────────────\${NC}"
275→
276→if [ "$CONFIGURED" -gt 0 ]; then
277→  success "\${CONFIGURED} MCP server(s) configured successfully."
278→fi
279→
280→if [ "$FAILED" -gt 0 ]; then
281→  warn "\${FAILED} configuration(s) skipped or failed."
282→fi
283→
284→echo ""
285→echo "  Your MCP tools are ready to use. Restart your editor(s) to load them."
286→echo "  Manage your collections at \${BOLD}https://tpmjs.com/@$USERNAME\${NC}"
287→echo ""
288→`;
289→
290→  return new Response(script, {
291→    headers: {
292→      'Content-Type': 'text/plain; charset=utf-8',
293→      'Cache-Control': 'no-cache',
294→    },
295→  });
296→}
