  1→'use client';
  2→
  3→import { Badge } from '@tpmjs/ui/Badge/Badge';
  4→import { Button } from '@tpmjs/ui/Button/Button';
  5→import { Container } from '@tpmjs/ui/Container/Container';
  6→import { Icon } from '@tpmjs/ui/Icon/Icon';
  7→import Link from 'next/link';
  8→import { useCallback, useEffect, useState } from 'react';
  9→import { useSession } from '@/lib/auth-client';
 10→import { AppHeader } from '~/components/AppHeader';
 11→
 12→const EDITORS = [
 13→  {
 14→    id: 'claude-code' as const,
 15→    name: 'Claude Code',
 16→    description: 'Terminal CLI by Anthropic',
 17→    icon: '>_',
 18→  },
 19→  {
 20→    id: 'cursor' as const,
 21→    name: 'Cursor',
 22→    description: 'AI code editor',
 23→    icon: '{;}',
 24→  },
 25→  {
 26→    id: 'windsurf' as const,
 27→    name: 'Windsurf',
 28→    description: 'Agentic IDE',
 29→    icon: 'W',
 30→  },
 31→  {
 32→    id: 'claude-desktop' as const,
 33→    name: 'Claude Desktop',
 34→    description: 'Desktop app',
 35→    icon: 'C',
 36→  },
 37→] as const;
 38→
 39→type EditorId = (typeof EDITORS)[number]['id'];
 40→
 41→interface Collection {
 42→  id: string;
 43→  name: string;
 44→  slug: string | null;
 45→  description: string | null;
 46→  isPublic: boolean;
 47→  toolCount: number;
 48→}
 49→
 50→interface Mapping {
 51→  collectionId: string;
 52→  collectionSlug: string;
 53→  collectionName: string;
 54→  editor: EditorId;
 55→}
 56→
 57→type Step = 'collections' | 'editors' | 'command';
 58→
 59→export default function SetupPage(): React.ReactElement {
 60→  const { data: session, isPending } = useSession();
 61→
 62→  const [collections, setCollections] = useState<Collection[]>([]);
 63→  const [isLoadingCollections, setIsLoadingCollections] = useState(true);
 64→  const [selectedCollections, setSelectedCollections] = useState<Set<string>>(new Set());
 65→  const [mappings, setMappings] = useState<Map<string, EditorId>>(new Map());
 66→  const [step, setStep] = useState<Step>('collections');
 67→  const [installCommand, setInstallCommand] = useState('');
 68→  const [apiKeyCreated, setApiKeyCreated] = useState<string | null>(null);
 69→  const [isGenerating, setIsGenerating] = useState(false);
 70→  const [error, setError] = useState<string | null>(null);
 71→  const [copied, setCopied] = useState(false);
 72→
 73→  const fetchCollections = useCallback(async () => {
 74→    try {
 75→      const response = await fetch('/api/collections?limit=50');
 76→      const data = await response.json();
 77→      if (data.success && data.data) {
 78→        setCollections(data.data);
 79→      }
 80→    } catch {
 81→      setError('Failed to load collections');
 82→    } finally {
 83→      setIsLoadingCollections(false);
 84→    }
 85→  }, []);
 86→
 87→  useEffect(() => {
 88→    if (session?.user) {
 89→      fetchCollections();
 90→    }
 91→  }, [session, fetchCollections]);
 92→
 93→  const toggleCollection = (id: string) => {
 94→    setSelectedCollections((prev) => {
 95→      const next = new Set(prev);
 96→      if (next.has(id)) {
 97→        next.delete(id);
 98→        setMappings((m) => {
 99→          const nm = new Map(m);
100→          nm.delete(id);
101→          return nm;
102→        });
103→      } else {
104→        next.add(id);
105→        // Default to claude-code
106→        setMappings((m) => {
107→          const nm = new Map(m);
108→          nm.set(id, 'claude-code');
109→          return nm;
110→        });
111→      }
112→      return next;
113→    });
114→  };
115→
116→  const setEditorForCollection = (collectionId: string, editor: EditorId) => {
117→    setMappings((m) => {
118→      const nm = new Map(m);
119→      nm.set(collectionId, editor);
120→      return nm;
121→    });
122→  };
123→
124→  const generateInstallCommand = async () => {
125→    setIsGenerating(true);
126→    setError(null);
127→
128→    try {
129→      const mappingPayload: Mapping[] = [];
130→      for (const id of selectedCollections) {
131→        const collection = collections.find((c) => c.id === id);
132→        if (!collection) continue;
133→        mappingPayload.push({
134→          collectionId: id,
135→          collectionSlug: collection.slug || collection.id,
136→          collectionName: collection.name,
137→          editor: mappings.get(id) || 'claude-code',
138→        });
139→      }
140→
141→      const response = await fetch('/api/setup/create-token', {
142→        method: 'POST',
143→        headers: { 'Content-Type': 'application/json' },
144→        body: JSON.stringify({
145→          mappings: mappingPayload,
146→          createApiKey: true,
147→        }),
148→      });
149→
150→      const data = await response.json();
151→
152→      if (!response.ok) {
153→        throw new Error(data.error || 'Failed to generate install command');
154→      }
155→
156→      setInstallCommand(data.installCommand);
157→      if (data.apiKey) {
158→        setApiKeyCreated(data.apiKey);
159→      }
160→      setStep('command');
161→    } catch (err) {
162→      setError(err instanceof Error ? err.message : 'Failed to generate install command');
163→    } finally {
164→      setIsGenerating(false);
165→    }
166→  };
167→
168→  const copyCommand = async () => {
169→    await navigator.clipboard.writeText(installCommand);
170→    setCopied(true);
171→    setTimeout(() => setCopied(false), 2000);
172→  };
173→
174→  // Not logged in
175→  if (!isPending && !session?.user) {
176→    return (
177→      <>
178→        <AppHeader />
179→        <main className="min-h-screen bg-background">
180→          <Container size="md" padding="lg" className="py-24">
181→            <div className="text-center">
182→              <div className="w-16 h-16 border border-dashed border-border bg-surface flex items-center justify-center mx-auto mb-6">
183→                <span className="font-mono text-2xl text-primary">$</span>
184→              </div>
185→              <h1 className="font-mono text-3xl md:text-4xl font-bold text-foreground mb-4 lowercase">
186→                set up tpmjs
187→              </h1>
188→              <p className="text-foreground-secondary mb-8 max-w-lg mx-auto">
189→                Sign in to select your collections and generate a personalized install command that
190→                configures your editors automatically.
191→              </p>
192→              <Link href="/auth/signin?callbackUrl=/setup">
193→                <Button size="lg" variant="default">
194→                  Sign In to Get Started
195→                </Button>
196→              </Link>
197→            </div>
198→          </Container>
199→        </main>
200→      </>
201→    );
202→  }
203→
204→  return (
205→    <>
206→      <AppHeader />
207→      <main className="min-h-screen bg-background">
208→        <Container size="lg" padding="lg" className="py-12 md:py-20">
209→          {/* Header */}
210→          <div className="text-center mb-12">
211→            <p className="font-mono text-xs text-primary uppercase tracking-widest mb-3">
212→              one command setup
213→            </p>
214→            <h1 className="font-mono text-3xl md:text-4xl font-bold text-foreground mb-4 lowercase">
215→              connect tpmjs to your editor
216→            </h1>
217→            <p className="text-foreground-secondary max-w-xl mx-auto">
218→              Select collections, choose your editors, and get a single command that configures
219→              everything.
220→            </p>
221→          </div>
222→
223→          {/* Progress Steps */}
224→          <div className="flex items-center justify-center gap-2 mb-12 font-mono text-sm">
225→            {(['collections', 'editors', 'command'] as Step[]).map((s, i) => (
226→              <div key={s} className="flex items-center gap-2">
227→                {i > 0 && (
228→                  <div
229→                    className={`w-8 h-px ${step === s || (['editors', 'command'].indexOf(step) > ['editors', 'command'].indexOf(s) ? true : false) ? 'bg-primary' : 'bg-border'}`}
230→                  />
231→                )}
232→                <button
233→                  type="button"
234→                  onClick={() => {
235→                    if (s === 'collections') setStep('collections');
236→                    else if (s === 'editors' && selectedCollections.size > 0) setStep('editors');
237→                  }}
238→                  className={`flex items-center gap-2 px-3 py-1.5 border transition-colors ${
239→                    step === s
240→                      ? 'border-primary text-primary bg-primary/5'
241→                      : 'border-border text-foreground-tertiary hover:text-foreground-secondary'
242→                  }`}
243→                >
244→                  <span className="w-5 h-5 border border-current flex items-center justify-center text-xs">
245→                    {i + 1}
246→                  </span>
247→                  <span className="hidden sm:inline lowercase">{s}</span>
248→                </button>
249→              </div>
250→            ))}
251→          </div>
252→
253→          {error && (
254→            <div className="mb-8 p-4 border border-error/30 bg-error/5 text-error text-sm font-mono">
255→              {error}
256→            </div>
257→          )}
258→
259→          {/* Step 1: Select Collections */}
260→          {step === 'collections' && (
261→            <div>
262→              <fieldset className="border border-dashed border-border p-6 md:p-8">
263→                <legend className="font-mono text-sm text-foreground-secondary px-3 lowercase">
264→                  select collections
265→                </legend>
266→
267→                {isPending || isLoadingCollections ? (
268→                  <div className="text-center py-12 text-foreground-tertiary font-mono text-sm">
269→                    Loading collections...
270→                  </div>
271→                ) : collections.length === 0 ? (
272→                  <div className="text-center py-12">
273→                    <p className="text-foreground-secondary mb-4">
274→                      You don&apos;t have any collections yet.
275→                    </p>
276→                    <Link href="/dashboard/collections">
277→                      <Button variant="default">Create a Collection</Button>
278→                    </Link>
279→                  </div>
280→                ) : (
281→                  <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
282→                    {collections.map((collection) => {
283→                      const isSelected = selectedCollections.has(collection.id);
284→                      return (
285→                        <button
286→                          key={collection.id}
287→                          type="button"
288→                          onClick={() => toggleCollection(collection.id)}
289→                          className={`text-left p-4 border transition-all ${
290→                            isSelected
291→                              ? 'border-primary bg-primary/5 ring-1 ring-primary'
292→                              : 'border-border bg-surface hover:border-foreground-tertiary'
293→                          }`}
294→                        >
295→                          <div className="flex items-start justify-between gap-2 mb-1">
296→                            <h3 className="font-mono text-sm font-semibold text-foreground">
297→                              {collection.name}
298→                            </h3>
299→                            <div className="flex items-center gap-2">
300→                              {collection.isPublic ? (
301→                                <Badge variant="outline" size="sm">
302→                                  public
303→                                </Badge>
304→                              ) : (
305→                                <Badge variant="secondary" size="sm">
306→                                  private
307→                                </Badge>
308→                              )}
309→                              <div
310→                                className={`w-4 h-4 border flex items-center justify-center transition-colors ${
311→                                  isSelected
312→                                    ? 'border-primary bg-primary text-white'
313→                                    : 'border-border'
314→                                }`}
315→                              >
316→                                {isSelected && <Icon icon="check" className="w-3 h-3" />}
317→                              </div>
318→                            </div>
319→                          </div>
320→                          {collection.description && (
321→                            <p className="text-xs text-foreground-secondary line-clamp-2 mb-2">
322→                              {collection.description}
323→                            </p>
324→                          )}
325→                          <span className="font-mono text-xs text-foreground-tertiary">
326→                            {collection.toolCount} tool{collection.toolCount !== 1 ? 's' : ''}
327→                          </span>
328→                        </button>
329→                      );
330→                    })}
331→                  </div>
332→                )}
333→              </fieldset>
334→
335→              <div className="flex justify-end mt-6">
336→                <Button
337→                  size="lg"
338→                  variant="default"
339→                  onClick={() => setStep('editors')}
340→                  disabled={selectedCollections.size === 0}
341→                >
342→                  Choose Editors ({selectedCollections.size} selected)
343→                </Button>
344→              </div>
345→            </div>
346→          )}
347→
348→          {/* Step 2: Map Collections to Editors */}
349→          {step === 'editors' && (
350→            <div>
351→              <fieldset className="border border-dashed border-border p-6 md:p-8">
352→                <legend className="font-mono text-sm text-foreground-secondary px-3 lowercase">
353→                  assign editors
354→                </legend>
355→
356→                <div className="space-y-4">
357→                  {Array.from(selectedCollections).map((collectionId) => {
358→                    const collection = collections.find((c) => c.id === collectionId);
359→                    if (!collection) return null;
360→                    const currentEditor = mappings.get(collectionId) || 'claude-code';
361→
362→                    return (
363→                      <div key={collectionId} className="p-4 border border-border bg-surface">
364→                        <div className="flex items-center justify-between mb-3">
365→                          <div>
366→                            <h3 className="font-mono text-sm font-semibold text-foreground">
367→                              {collection.name}
368→                            </h3>
369→                            <span className="font-mono text-xs text-foreground-tertiary">
370→                              {collection.toolCount} tool{collection.toolCount !== 1 ? 's' : ''}
371→                            </span>
372→                          </div>
373→                          <Icon icon="arrowRight" className="w-4 h-4 text-foreground-tertiary" />
374→                        </div>
375→                        <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
376→                          {EDITORS.map((editor) => (
377→                            <button
378→                              key={editor.id}
379→                              type="button"
380→                              onClick={() => setEditorForCollection(collectionId, editor.id)}
381→                              className={`p-3 border text-center transition-all ${
382→                                currentEditor === editor.id
383→                                  ? 'border-primary bg-primary/5 ring-1 ring-primary'
384→                                  : 'border-border hover:border-foreground-tertiary'
385→                              }`}
386→                            >
387→                              <div className="font-mono text-lg mb-1">{editor.icon}</div>
388→                              <div className="font-mono text-xs font-medium text-foreground">
389→                                {editor.name}
390→                              </div>
391→                            </button>
392→                          ))}
393→                        </div>
394→                      </div>
395→                    );
396→                  })}
397→                </div>
398→              </fieldset>
399→
400→              <div className="flex justify-between mt-6">
401→                <Button variant="outline" onClick={() => setStep('collections')}>
402→                  Back
403→                </Button>
404→                <Button
405→                  size="lg"
406→                  variant="default"
407→                  onClick={generateInstallCommand}
408→                  disabled={isGenerating}
409→                >
410→                  {isGenerating ? 'Generating...' : 'Generate Install Command'}
411→                </Button>
412→              </div>
413→            </div>
414→          )}
415→
416→          {/* Step 3: Copy Command */}
417→          {step === 'command' && (
418→            <div>
419→              <fieldset className="border border-dashed border-border p-6 md:p-8">
420→                <legend className="font-mono text-sm text-foreground-secondary px-3 lowercase">
421→                  your install command
422→                </legend>
423→
424→                <p className="text-sm text-foreground-secondary mb-6">
425→                  Run this in your terminal to configure all selected editors. The token expires in
