import { randomBytes } from 'node:crypto';
import { prisma } from '@tpmjs/db';
import { NextResponse } from 'next/server';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 60;

/**
 * POST /api/setup/claim
 *
 * Creates a claim code that the install.sh script uses to poll for setup completion.
 * No auth required - the claim code is the secret.
 * Creates a placeholder SetupToken with empty config that gets filled in
 * when the user completes setup on the web UI.
 */
export async function POST() {
  try {
    const claimCode = randomBytes(12).toString('hex'); // 24-char hex
    const token = randomBytes(32).toString('hex'); // 64-char hex
    const expiresAt = new Date(Date.now() + 10 * 60 * 1000); // 10 min expiry for claims

    // Create a placeholder token — no userId yet, config is empty.
    // The setup page will update this when the user completes the flow.
    // We use a special "unclaimed" user ID since userId is required.
    // The setup page will replace this with the real user.
    await prisma.setupToken.create({
      data: {
        // Temporary: we need a userId but don't have one yet.
        // We'll use upsert in create-token to replace this.
        userId: 'claim_pending',
        token,
        claimCode,
        config: { pending: true },
        expiresAt,
      },
    });

    return NextResponse.json({
      claimCode,
      setupUrl: `https://tpmjs.com/setup?claim=${claimCode}`,
    });
  } catch (error) {
    console.error('[Setup] Error creating claim:', error);
    return NextResponse.json({ error: 'Failed to create claim' }, { status: 500 });
  }
}

