  RED='\\033[0;31m'
  GREEN='\\033[0;32m'
  YELLOW='\\033[1;33m'
  BLUE='\\033[0;34m'
  CYAN='\\033[0;36m'
  BOLD='\\033[1m'
  NC='\\033[0m'
else
  RED='' GREEN='' YELLOW='' BLUE='' CYAN='' BOLD='' NC=''
fi

info()    { echo -e "\${BLUE}[info]\${NC}  $1"; }
success() { echo -e "\${GREEN}[ok]\${NC}    $1"; }
warn()    { echo -e "\${YELLOW}[warn]\${NC}  $1"; }
error()   { echo -e "\${RED}[error]\${NC} $1"; }

# Banner
