 10→import { useSession } from '@/lib/auth-client';
 11→import { AppHeader } from '~/components/AppHeader';
 12→
 13→const EDITORS = [
 14→  {
 15→    id: 'claude-code' as const,
 16→    name: 'Claude Code',
 17→    description: 'Terminal CLI by Anthropic',
 18→    icon: '>_',
