 33→    id: 'claude-desktop' as const,
 34→    name: 'Claude Desktop',
 35→    description: 'Desktop app',
 36→    icon: 'C',
 37→  },
 38→] as const;
 39→
 40→type EditorId = (typeof EDITORS)[number]['id'];
 41→
 42→interface Collection {
 43→  id: string;
 44→  name: string;
 45→  slug: string | null;
 46→  description: string | null;
 47→  isPublic: boolean;
 48→  toolCount: number;
 49→}
 50→
 51→interface Mapping {
 52→  collectionId: string;
 53→  collectionSlug: string;
 54→  collectionName: string;
 55→  editor: EditorId;
 56→}
 57→
 58→type Step = 'collections' | 'editors' | 'command';
 59→
 60→export default function SetupPage(): React.ReactElement {
 61→  const { data: session, isPending } = useSession();
 62→  const searchParams = useSearchParams();
 63→  const claimCode = searchParams.get('claim');
 64→
 65→  const [collections, setCollections] = useState<Collection[]>([]);
 66→  const [isLoadingCollections, setIsLoadingCollections] = useState(true);
 67→  const [selectedCollections, setSelectedCollections] = useState<Set<string>>(new Set());
 68→  const [mappings, setMappings] = useState<Map<string, EditorId>>(new Map());
 69→  const [step, setStep] = useState<Step>('collections');
 70→  const [installCommand, setInstallCommand] = useState('');
 71→  const [apiKeyCreated, setApiKeyCreated] = useState<string | null>(null);
 72→  const [isGenerating, setIsGenerating] = useState(false);
 73→  const [error, setError] = useState<string | null>(null);
 74→  const [copied, setCopied] = useState(false);
 75→  const [claimCompleted, setClaimCompleted] = useState(false);
 76→
 77→  const fetchCollections = useCallback(async () => {
 78→    try {
 79→      const response = await fetch('/api/collections?limit=50');
 80→      const data = await response.json();
 81→      if (data.success && data.data) {
 82→        setCollections(data.data);
 83→      }
 84→    } catch {
 85→      setError('Failed to load collections');
 86→    } finally {
 87→      setIsLoadingCollections(false);
 88→    }
 89→  }, []);
 90→
 91→  useEffect(() => {
 92→    if (session?.user) {
 93→      fetchCollections();
 94→    }
 95→  }, [session, fetchCollections]);
 96→
 97→  const toggleCollection = (id: string) => {
 98→    setSelectedCollections((prev) => {
 99→      const next = new Set(prev);
100→      if (next.has(id)) {
101→        next.delete(id);
102→        setMappings((m) => {
103→          const nm = new Map(m);
104→          nm.delete(id);
105→          return nm;
106→        });
107→      } else {
108→        next.add(id);
109→        // Default to claude-code
110→        setMappings((m) => {
111→          const nm = new Map(m);
112→          nm.set(id, 'claude-code');
113→          return nm;
114→        });
115→      }
116→      return next;
117→    });
118→  };
119→
120→  const setEditorForCollection = (collectionId: string, editor: EditorId) => {
121→    setMappings((m) => {
122→      const nm = new Map(m);
123→      nm.set(collectionId, editor);
124→      return nm;
125→    });
126→  };
127→
128→  const generateInstallCommand = async () => {
129→    setIsGenerating(true);
130→    setError(null);
131→
132→    try {
133→      const mappingPayload: Mapping[] = [];
134→      for (const id of selectedCollections) {
135→        const collection = collections.find((c) => c.id === id);
136→        if (!collection) continue;
137→        mappingPayload.push({
138→          collectionId: id,
139→          collectionSlug: collection.slug || collection.id,
140→          collectionName: collection.name,
141→          editor: mappings.get(id) || 'claude-code',
142→        });
143→      }
144→
145→      const response = await fetch('/api/setup/create-token', {
146→        method: 'POST',
147→        headers: { 'Content-Type': 'application/json' },
148→        body: JSON.stringify({
149→          mappings: mappingPayload,
150→          createApiKey: true,
151→          ...(claimCode && { claimCode }),
152→        }),
153→      });
154→
155→      const data = await response.json();
156→
157→      if (!response.ok) {
158→        throw new Error(data.error || 'Failed to generate install command');
159→      }
160→
161→      setInstallCommand(data.installCommand);
162→      if (data.apiKey) {
163→        setApiKeyCreated(data.apiKey);
164→      }
165→
166→      // If this was triggered from install.sh (claim code present),
167→      // show a completion message instead of a command to copy
168→      if (claimCode) {
169→        setClaimCompleted(true);
170→      }
171→
172→      setStep('command');
173→    } catch (err) {
174→      setError(err instanceof Error ? err.message : 'Failed to generate install command');
175→    } finally {
176→      setIsGenerating(false);
177→    }
178→  };
179→
180→  const copyCommand = async () => {
181→    await navigator.clipboard.writeText(installCommand);
182→    setCopied(true);
183→    setTimeout(() => setCopied(false), 2000);
184→  };
185→
186→  // Not logged in
187→  if (!isPending && !session?.user) {
188→    return (
189→      <>
190→        <AppHeader />
191→        <main className="min-h-screen bg-background">
192→          <Container size="md" padding="lg" className="py-24">
193→            <div className="text-center">
194→              <div className="w-16 h-16 border border-dashed border-border bg-surface flex items-center justify-center mx-auto mb-6">
195→                <span className="font-mono text-2xl text-primary">$</span>
196→              </div>
197→              <h1 className="font-mono text-3xl md:text-4xl font-bold text-foreground mb-4 lowercase">
198→                set up tpmjs
199→              </h1>
200→              <p className="text-foreground-secondary mb-8 max-w-lg mx-auto">
201→                Sign in to select your collections and generate a personalized install command that
202→                configures your editors automatically.
203→              </p>
204→              <Link href="/auth/signin?callbackUrl=/setup">
205→                <Button size="lg" variant="default">
206→                  Sign In to Get Started
207→                </Button>
208→              </Link>
209→            </div>
210→          </Container>
211→        </main>
212→      </>
213→    );
214→  }
215→
216→  return (
217→    <>
218→      <AppHeader />
219→      <main className="min-h-screen bg-background">
220→        <Container size="lg" padding="lg" className="py-12 md:py-20">
221→          {/* CLI-initiated banner */}
222→          {claimCode && !claimCompleted && (
223→            <div className="mb-8 p-4 border-2 border-primary bg-primary/5 text-center">
224→              <p className="font-mono text-sm text-foreground">
225→                Your terminal is waiting. Select your collections and editors below, then click
226→                generate — your terminal will pick up the configuration automatically.
227→              </p>
228→            </div>
229→          )}
230→
231→          {/* Header */}
232→          <div className="text-center mb-12">
233→            <p className="font-mono text-xs text-primary uppercase tracking-widest mb-3">
234→              one command setup
235→            </p>
236→            <h1 className="font-mono text-3xl md:text-4xl font-bold text-foreground mb-4 lowercase">
237→              connect tpmjs to your editor
238→            </h1>
239→            <p className="text-foreground-secondary max-w-xl mx-auto">
240→              Select collections, choose your editors, and get a single command that configures
241→              everything.
242→            </p>
243→          </div>
244→
245→          {/* Progress Steps */}
246→          <div className="flex items-center justify-center gap-2 mb-12 font-mono text-sm">
247→            {(['collections', 'editors', 'command'] as Step[]).map((s, i) => (
248→              <div key={s} className="flex items-center gap-2">
249→                {i > 0 && (
250→                  <div
251→                    className={`w-8 h-px ${step === s || (['editors', 'command'].indexOf(step) > ['editors', 'command'].indexOf(s) ? true : false) ? 'bg-primary' : 'bg-border'}`}
252→                  />
253→                )}
254→                <button
255→                  type="button"
256→                  onClick={() => {
257→                    if (s === 'collections') setStep('collections');
258→                    else if (s === 'editors' && selectedCollections.size > 0) setStep('editors');
259→                  }}
260→                  className={`flex items-center gap-2 px-3 py-1.5 border transition-colors ${
261→                    step === s
262→                      ? 'border-primary text-primary bg-primary/5'
263→                      : 'border-border text-foreground-tertiary hover:text-foreground-secondary'
264→                  }`}
265→                >
