277→              {error}
278→            </div>
279→          )}
280→
281→          {/* Step 1: Select Collections */}
282→          {step === 'collections' && (
283→            <div>
284→              <fieldset className="border border-dashed border-border p-6 md:p-8">
285→                <legend className="font-mono text-sm text-foreground-secondary px-3 lowercase">
286→                  select collections
287→                </legend>
288→
289→                {isPending || isLoadingCollections ? (
290→                  <div className="text-center py-12 text-foreground-tertiary font-mono text-sm">
291→                    Loading collections...
292→                  </div>
293→                ) : collections.length === 0 ? (
294→                  <div className="text-center py-12">
295→                    <p className="text-foreground-secondary mb-4">
296→                      You don&apos;t have any collections yet.
297→                    </p>
298→                    <Link href="/dashboard/collections">
299→                      <Button variant="default">Create a Collection</Button>
300→                    </Link>
301→                  </div>
302→                ) : (
303→                  <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
304→                    {collections.map((collection) => {
305→                      const isSelected = selectedCollections.has(collection.id);
306→                      return (
307→                        <button
308→                          key={collection.id}
309→                          type="button"
310→                          onClick={() => toggleCollection(collection.id)}
311→                          className={`text-left p-4 border transition-all ${
